{
  "name": "last-circle",
  "private": true,
  "version": "1.0.0",
  "description": "LAST CIRCLE - a 3D battle royale with base building, running in the browser.",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002",
    "test": "node --test tests/*.test.mjs"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

/* ============================================================
   LAST CIRCLE — battle royale UI
   ============================================================ */
@font-face { font-family: 'Barlow Condensed'; font-style: normal; font-weight: 500; font-display: swap; src: url('/fonts/BarlowCondensed-500.woff2') format('woff2'); }
@font-face { font-family: 'Barlow Condensed'; font-style: normal; font-weight: 600; font-display: swap; src: url('/fonts/BarlowCondensed-600.woff2') format('woff2'); }
@font-face { font-family: 'Barlow Condensed'; font-style: normal; font-weight: 700; font-display: swap; src: url('/fonts/BarlowCondensed-700.woff2') format('woff2'); }
@font-face { font-family: 'Barlow Condensed'; font-style: normal; font-weight: 800; font-display: swap; src: url('/fonts/BarlowCondensed-800.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 400; font-display: swap; src: url('/fonts/Rajdhani-400.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 500; font-display: swap; src: url('/fonts/Rajdhani-500.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 600; font-display: swap; src: url('/fonts/Rajdhani-600.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 700; font-display: swap; src: url('/fonts/Rajdhani-700.woff2') format('woff2'); }

:root {
  --bg: #0a0c0d;
  --ink: #ece9e1;
  --muted: #9ba3a3;
  --dim: #6d7676;
  --orange: #ff7a18;
  --orange-hot: #ff9a3d;
  --orange-soft: rgba(255, 122, 24, 0.16);
  --blue: #6dc4ff;
  --blue-soft: rgba(70, 160, 255, 0.18);
  --red: #e8483f;
  --panel: rgba(10, 13, 14, 0.74);
  --panel-solid: #101415;
  --line: rgba(255, 255, 255, 0.13);
  --line-soft: rgba(255, 255, 255, 0.07);
  --safe: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
  --hud-scale: 1;
  --spread: 7px;
  font-synthesis: none;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

kbd {
  display: inline-block;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.06em;
  line-height: 1;
  padding: 4px 6px 3px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-bottom-width: 2px;
  border-radius: 2px;
  color: #f2efe7;
  background: rgba(255, 255, 255, 0.07);
  vertical-align: middle;
}

.screen { position: absolute; inset: 0; z-index: 30; }
.screen.hidden { display: none !important; }
#hud.hidden, #touch.hidden { display: none !important; }

/* ============================================================
   MENU
   ============================================================ */
#menu {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(26px + var(--safe-top)) clamp(22px, 4vw, 64px) calc(22px + var(--safe)) clamp(22px, 4vw, 64px);
  background:
    radial-gradient(120% 90% at 32% 48%, rgba(4, 6, 7, 0.05) 0%, rgba(4, 6, 7, 0.55) 58%, rgba(4, 6, 7, 0.92) 100%),
    linear-gradient(90deg, rgba(6, 8, 9, 0.88) 0%, rgba(6, 8, 9, 0.45) 46%, rgba(6, 8, 9, 0.72) 100%);
  opacity: 1;
  transition: opacity 0.55s ease, visibility 0.55s;
}
#menu.closing { opacity: 0; visibility: hidden; }
#menu::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.022) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
  opacity: 0.5;
}
#menu::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 46%, transparent 42%, rgba(0, 0, 0, 0.55) 100%);
}

.menu-frame {
  position: relative;
  z-index: 2;
  width: min(1500px, 100%);
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
}

.menu-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 30px; height: 30px; color: var(--orange); display: inline-flex; filter: drop-shadow(0 0 10px rgba(255, 122, 24, 0.4)); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-name { font-family: 'Barlow Condensed', sans-serif; font-weight: 600; font-size: 15px; letter-spacing: 0.26em; color: #d9d6cd; }
.brand-name em { color: var(--orange); font-style: normal; margin: 0 2px; }
.menu-meta { font-family: 'Rajdhani', sans-serif; font-weight: 600; font-size: 12px; letter-spacing: 0.2em; color: #c1c5c1; display: flex; align-items: center; gap: 8px; }
.menu-meta .sep { color: #5c6565; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 0 0 rgba(255, 122, 24, 0.6); animation: pulse 2.4s infinite; }

.menu-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 396px;
  align-items: center;
  gap: clamp(24px, 4vw, 72px);
  flex: 1;
  min-height: 0;
}

.menu-hero { max-width: 830px; padding-left: clamp(0px, 2vw, 36px); }
.eyebrow {
  display: flex; align-items: center; gap: 10px;
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 12px; letter-spacing: 0.34em;
  color: var(--orange); text-transform: uppercase; margin-bottom: 16px;
}
.eyebrow .bar { width: 34px; height: 2px; background: var(--orange); display: inline-block; box-shadow: 0 0 12px rgba(255, 122, 24, 0.7); }

.title {
  margin: 0;
  font-family: 'Barlow Condensed', sans-serif;
  font-weight: 800;
  font-size: clamp(80px, 12.5vw, 190px);
  line-height: 0.78;
  letter-spacing: -0.015em;
  text-transform: uppercase;
  color: #f4f1e9;
  text-shadow: 0 12px 60px rgba(0, 0, 0, 0.65);
  margin-bottom: 22px;
}
.title span {
  display: inline;
  color: transparent;
  -webkit-text-stroke: 2px rgba(255, 122, 24, 0.92);
  text-shadow: 0 0 44px rgba(255, 122, 24, 0.18);
  margin-left: 0.06em;
}
.tagline { margin: 0 0 12px; font-family: 'Barlow Condensed', sans-serif; font-weight: 600; font-size: clamp(20px, 2vw, 28px); letter-spacing: 0.18em; text-transform: uppercase; color: #e2ded4; }
.lede { margin: 0 0 30px; max-width: 600px; font-size: 15px; line-height: 1.55; letter-spacing: 0.02em; color: #b4bab8; font-weight: 500; }

.menu-actions { display: flex; align-items: center; gap: 28px; flex-wrap: wrap; }
.btn-primary {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  justify-content: center;
  min-width: 286px;
  padding: 17px 58px 16px 26px;
  border: 0;
  cursor: pointer;
  text-align: left;
  background: linear-gradient(100deg, #ff6a08 0%, #ff8a2c 55%, #ff9f4d 100%);
  color: #170d05;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  transition: transform 0.18s ease, filter 0.18s ease, box-shadow 0.18s ease;
  box-shadow: 0 10px 40px rgba(255, 100, 10, 0.18);
}
.btn-primary::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(100deg, transparent 20%, rgba(255, 255, 255, 0.35) 46%, transparent 62%);
  transform: translateX(-130%);
  transition: transform 0.55s ease;
}
.btn-primary:hover { filter: brightness(1.08); transform: translateY(-1px); box-shadow: 0 14px 50px rgba(255, 100, 10, 0.32); }
.btn-primary:hover::after { transform: translateX(130%); }
.btn-primary:active { transform: translateY(1px) scale(0.995); }
.btn-primary .btn-label { font-family: 'Barlow Condensed', sans-serif; font-weight: 800; font-size: 26px; letter-spacing: 0.14em; text-transform: uppercase; line-height: 1; }
.btn-primary .btn-sub { font-family: 'Rajdhani', sans-serif; font-weight: 600; font-size: 10px; letter-spacing: 0.24em; text-transform: uppercase; opacity: 0.66; margin-top: 5px; }
.btn-primary .btn-arrow { position: absolute; right: 22px; top: 50%; transform: translateY(-50%); font-size: 14px; opacity: 0.85; }
.btn-primary.small { min-width: 200px; padding: 14px 40px 13px 20px; }
.btn-primary.small .btn-label { font-size: 20px; }

.menu-hint { display: flex; flex-direction: column; gap: 7px; font-size: 11px; font-weight: 600; letter-spacing: 0.13em; color: #8f9795; text-transform: uppercase; }
.menu-hint span { display: flex; align-items: center; gap: 8px; }

.feature-strip {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px;
  margin-top: 36px; background: var(--line-soft);
  border-top: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft);
}
.feature { padding: 15px 16px 16px; background: rgba(8, 11, 12, 0.42); backdrop-filter: blur(5px); }
.feature strong { display: block; font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: 0.22em; color: var(--orange); margin-bottom: 5px; }
.feature span { display: block; font-size: 11.5px; line-height: 1.4; letter-spacing: 0.03em; color: #949c9a; font-weight: 500; }

/* Brief panel */
.menu-panel {
  width: 100%;
  background: linear-gradient(160deg, rgba(16, 21, 22, 0.9), rgba(7, 10, 11, 0.86));
  border: 1px solid var(--line);
  backdrop-filter: blur(14px);
  padding: 18px 18px 14px;
  position: relative;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
}
.menu-panel::before, .menu-panel::after {
  content: ''; position: absolute; width: 26px; height: 2px; background: var(--orange);
}
.menu-panel::before { top: 0; left: 0; }
.menu-panel::after { bottom: 0; right: 0; }
.panel-head { display: flex; justify-content: space-between; align-items: center; font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 11px; letter-spacing: 0.26em; color: #cfd2cb; border-bottom: 1px solid var(--line-soft); padding-bottom: 10px; }
.panel-code { color: var(--orange); }

.brief-map {
  position: relative; margin: 14px 0 12px; aspect-ratio: 1;
  background: #0a1411;
  border: 1px solid rgba(255, 255, 255, 0.09);
  overflow: hidden;
}
#briefMap { position: absolute; inset: 0; width: 100%; height: 100%; }
.map-grid {
  position: absolute; inset: 0;
  background-image: linear-gradient(rgba(120, 200, 170, 0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(120, 200, 170, 0.1) 1px, transparent 1px);
  background-size: 10% 10%;
  mix-blend-mode: screen;
}
.brief-map::after {
  content: ''; position: absolute; left: 0; right: 0; height: 35%; top: -40%;
  background: linear-gradient(180deg, transparent, rgba(120, 255, 200, 0.07), transparent);
  animation: scan 5.5s linear infinite;
}
.map-label { position: absolute; font-family: 'Barlow Condensed', sans-serif; font-size: 11px; font-weight: 700; color: rgba(200, 235, 220, 0.7); letter-spacing: 0.1em; }
.map-label.n { top: 6px; left: 50%; transform: translateX(-50%); }
.map-label.s { bottom: 6px; left: 50%; transform: translateX(-50%); }
.map-label.e { right: 8px; top: 50%; transform: translateY(-50%); }
.map-label.w { left: 8px; top: 50%; transform: translateY(-50%); }
.map-ping { position: absolute; width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 0 4px rgba(255, 122, 24, 0.16), 0 0 18px var(--orange); }
.map-ping::after { content: ''; position: absolute; inset: -6px; border: 1px solid rgba(255, 122, 24, 0.5); border-radius: 50%; animation: ping 2.2s ease-out infinite; }
.map-zone { position: absolute; left: 50%; top: 48%; width: 66%; height: 66%; margin: -33% 0 0 -33%; border: 1px dashed rgba(110, 195, 255, 0.5); border-radius: 50%; box-shadow: inset 0 0 40px rgba(70, 160, 255, 0.08); }

.brief-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line-soft); border: 1px solid var(--line-soft); margin-bottom: 12px; }
.brief-stats div { background: rgba(8, 11, 12, 0.6); padding: 8px 10px; }
.brief-stats span { display: block; font-size: 9px; font-weight: 700; letter-spacing: 0.22em; color: #77807e; }
.brief-stats strong { display: block; font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 18px; letter-spacing: 0.06em; color: #e6e2d8; }

.settings { display: flex; flex-direction: column; gap: 9px; }
.setting { display: grid; grid-template-columns: 84px 1fr auto; align-items: center; gap: 10px; font-size: 10px; font-weight: 700; letter-spacing: 0.18em; color: #88918f; text-transform: uppercase; }
.setting select {
  appearance: none; width: 100%; padding: 6px 9px;
  background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); color: #dfe2da;
  font-family: 'Rajdhani', sans-serif; font-weight: 600; font-size: 11px; letter-spacing: 0.14em;
  cursor: pointer; outline: none;
}
.setting select:focus-visible { border-color: var(--orange); }
.setting input[type='range'] { width: 100%; accent-color: var(--orange); height: 2px; cursor: pointer; }
.setting output { font-family: 'Rajdhani', sans-serif; font-weight: 600; font-size: 11px; color: #ccd0c8; letter-spacing: 0.08em; width: 30px; text-align: right; }
.setting.toggle { grid-template-columns: 84px 1fr auto; }
.setting.toggle input { display: none; }
.setting.toggle .switch { position: relative; width: 40px; height: 20px; background: rgba(255, 255, 255, 0.08); border: 1px solid var(--line); border-radius: 20px; transition: 0.2s; }
.setting.toggle .switch::after { content: ''; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: #88918f; transition: 0.2s; }
.setting.toggle input:checked + .switch { background: rgba(255, 122, 24, 0.22); border-color: rgba(255, 122, 24, 0.55); }
.setting.toggle input:checked + .switch::after { left: 22px; background: var(--orange); box-shadow: 0 0 10px rgba(255, 122, 24, 0.7); }
.panel-note { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--line-soft); font-size: 10px; letter-spacing: 0.2em; color: #5e6866; text-align: center; text-transform: uppercase; font-weight: 600; }

.menu-foot { display: flex; justify-content: space-between; gap: 18px; font-size: 10px; font-weight: 600; letter-spacing: 0.16em; color: #6e7775; text-transform: uppercase; border-top: 1px solid var(--line-soft); padding-top: 12px; }

/* ============================================================
   HUD
   ============================================================ */
#hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; opacity: 1; transition: opacity 0.4s; }
#hud.hidden { opacity: 0; visibility: hidden; }

.hud-top { position: absolute; top: calc(10px + var(--safe-top)); left: 0; right: 0; display: flex; justify-content: center; }
#compass { position: absolute; top: 0; width: min(600px, 52vw); height: 40px; opacity: 0.9; }
#zoneBanner {
  position: absolute; top: 46px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px;
  padding: 5px 14px 4px;
  background: rgba(6, 9, 10, 0.55); border: 1px solid var(--line-soft); border-radius: 2px;
  backdrop-filter: blur(6px);
  font-family: 'Rajdhani', sans-serif; font-size: 11px; font-weight: 700; letter-spacing: 0.16em;
}
.zone-kicker { color: #7f8b8b; font-size: 9px; letter-spacing: 0.22em; }
#zoneTimer { font-size: 15px; font-weight: 700; color: #eae6dc; font-variant-numeric: tabular-nums; }
.zone-state { color: var(--orange); font-size: 9px; letter-spacing: 0.16em; }
#zoneBanner.danger .zone-state, #zoneBanner.closing .zone-state { color: #ff5c4d; }
#zoneBanner.closing { border-color: rgba(255, 92, 77, 0.4); }

.match-counts {
  position: absolute; top: 4px; right: 18px;
  display: flex; gap: 18px; align-items: flex-start;
  background: linear-gradient(180deg, rgba(6, 9, 10, 0.74), rgba(6, 9, 10, 0.42));
  border: 1px solid var(--line-soft); border-radius: 2px;
  padding: 8px 14px 7px;
  backdrop-filter: blur(8px);
}
.count { display: flex; flex-direction: column; align-items: flex-end; }
.count span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 27px; line-height: 0.9; color: #f2efe6; font-variant-numeric: tabular-nums; }
.count small { font-size: 8px; font-weight: 700; letter-spacing: 0.24em; color: #8b9492; margin-top: 4px; }
.count.divider { border-left: 1px solid var(--line-soft); padding-left: 18px; }
.count.divider span { color: var(--orange); }

#killfeed {
  position: absolute; top: 74px; right: 18px;
  display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
  width: 330px;
}
.feed-item {
  display: flex; align-items: center; gap: 8px;
  padding: 5px 9px;
  background: rgba(6, 9, 10, 0.65);
  border-right: 2px solid var(--orange);
  font-family: 'Rajdhani', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0.04em;
  color: #cfd3cc;
  animation: feedIn 0.25s ease both;
  backdrop-filter: blur(5px);
}
.feed-item.fade { opacity: 0; transition: opacity 0.6s; }
.feed-item b { color: #f2efe6; font-weight: 700; }
.feed-item .weapon { color: var(--orange); font-size: 10px; letter-spacing: 0.1em; }
.feed-item .hs { color: #ffd257; font-size: 9px; letter-spacing: 0.16em; }
.feed-item.player { border-right-color: var(--orange); background: rgba(255, 122, 24, 0.12); }
.feed-item.player b:last-of-type { color: #ffb066; }

#zoneWarning {
  position: absolute; top: 96px; left: 50%; transform: translateX(-50%);
  display: none; flex-direction: column; align-items: center; gap: 2px;
  padding: 8px 20px;
  border: 1px solid rgba(255, 70, 55, 0.55);
  background: rgba(70, 8, 4, 0.55);
  box-shadow: 0 0 40px rgba(255, 40, 20, 0.25);
  animation: dangerPulse 1.4s ease-in-out infinite;
}
#zoneWarning.show { display: flex; }
#zoneWarning strong { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #ff6656; }
#zoneWarning span { font-size: 9px; font-weight: 700; letter-spacing: 0.2em; color: #ffb5aa; }

/* crosshair */
#crosshair {
  position: absolute; left: 50%; top: 50%; width: 2px; height: 2px;
  --gap: calc(var(--spread) + 3px);
  opacity: 0.95;
  transition: opacity 0.15s;
}
#crosshair.hide { opacity: 0; }
.ch-dot { position: absolute; left: -1px; top: -1px; width: 3px; height: 3px; background: #f4f1e8; border-radius: 50%; box-shadow: 0 0 4px rgba(0, 0, 0, 0.9); }
.ch-line { position: absolute; background: #f4f1e8; box-shadow: 0 0 3px rgba(0, 0, 0, 0.9), 0 0 1px rgba(0, 0, 0, 1); opacity: 0.9; transition: transform 0.08s ease-out; }
.ch-line.t { width: 2px; height: 9px; left: -1px; top: calc(-1 * var(--gap) - 9px); }
.ch-line.b { width: 2px; height: 9px; left: -1px; top: var(--gap); }
.ch-line.l { width: 9px; height: 2px; top: -1px; left: calc(-1 * var(--gap) - 9px); }
.ch-line.r { width: 9px; height: 2px; top: -1px; left: var(--gap); }

#hitmarker { position: absolute; left: 50%; top: 50%; width: 0; height: 0; opacity: 0; }
#hitmarker span { position: absolute; width: 2px; height: 9px; background: #fff; box-shadow: 0 0 4px rgba(0, 0, 0, 0.8); left: -1px; top: -4px; }
#hitmarker span:nth-child(1) { transform: rotate(45deg) translate(0, -13px); }
#hitmarker span:nth-child(2) { transform: rotate(45deg) translate(0, 13px); }
#hitmarker span:nth-child(3) { transform: rotate(-45deg) translate(0, -13px); }
#hitmarker span:nth-child(4) { transform: rotate(-45deg) translate(0, 13px); }
#hitmarker.show { animation: hitPop 0.28s ease-out; }
#hitmarker.headshot span { background: #ffd257; }
#hitmarker.kill span { background: #ff5a45; }

#damageDir {
  position: absolute; left: 50%; top: 50%; width: 170px; height: 170px; margin: -85px 0 0 -85px;
  border-radius: 50%; opacity: 0; pointer-events: none;
  background: conic-gradient(from 0deg, transparent 0deg, rgba(255, 45, 30, 0.55) 16deg, transparent 34deg);
  filter: blur(2px);
  transition: opacity 0.1s;
}
#damageVignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 38%, rgba(160, 12, 6, 0.45) 82%, rgba(120, 5, 2, 0.72) 100%);
  transition: opacity 0.25s;
}
#damageVignette.zone {
  opacity: 0.55;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(20, 80, 160, 0.3) 78%, rgba(10, 50, 120, 0.6) 100%);
  animation: zoneVignette 2s ease-in-out infinite;
}

/* prompts */
#interactPrompt, #harvestPrompt {
  position: absolute; left: 50%; top: 61%; transform: translateX(-50%);
  display: none; align-items: center; gap: 9px;
  padding: 7px 14px 7px 9px;
  background: rgba(7, 10, 11, 0.78);
  border: 1px solid rgba(255, 122, 24, 0.4);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 12px; letter-spacing: 0.16em;
  backdrop-filter: blur(6px);
}
#interactPrompt.show, #harvestPrompt.show { display: flex; }
#interactPrompt kbd, #harvestPrompt kbd { border-color: var(--orange); color: var(--orange); background: rgba(255, 122, 24, 0.1); }
#harvestPrompt { top: 66%; }

#healProgress {
  position: absolute; left: 50%; top: 57%; transform: translateX(-50%);
  display: none; width: 220px; flex-direction: column; gap: 5px;
}
#healProgress.show { display: flex; }
.heal-label { font-size: 9px; font-weight: 700; letter-spacing: 0.22em; color: #9ee7b2; text-align: center; }
.heal-track { height: 3px; background: rgba(255, 255, 255, 0.16); overflow: hidden; }
.heal-track i { display: block; height: 100%; width: 0%; background: #7ce69a; box-shadow: 0 0 10px rgba(124, 230, 154, 0.7); }

/* build hud */
#buildHud {
  position: absolute; left: 50%; bottom: calc(118px + var(--safe)); transform: translateX(-50%);
  display: none; flex-direction: column; align-items: center; gap: 8px;
  padding: 10px 14px 11px;
  background: rgba(7, 10, 11, 0.74);
  border: 1px solid rgba(255, 122, 24, 0.28);
  backdrop-filter: blur(8px);
  min-width: 390px;
}
#buildHud.show { display: flex; }
.build-title { display: flex; align-items: baseline; gap: 12px; }
.build-title span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: 0.22em; color: var(--orange); }
.build-title small { font-size: 8px; font-weight: 700; letter-spacing: 0.14em; color: #75807e; }
.build-pieces { display: flex; gap: 6px; }
.piece {
  position: relative; display: flex; align-items: center; gap: 7px;
  padding: 7px 12px 7px 7px; min-width: 100px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03);
  transition: 0.15s;
}
.piece.active { border-color: var(--orange); background: rgba(255, 122, 24, 0.14); box-shadow: inset 0 0 20px rgba(255, 122, 24, 0.08); }
.piece b { width: 18px; height: 18px; display: grid; place-items: center; font-size: 10px; background: rgba(255, 255, 255, 0.1); color: #e8e4da; }
.piece.active b { background: var(--orange); color: #170d05; }
.piece span { font-size: 10px; font-weight: 700; letter-spacing: 0.16em; color: #c8cdc6; }
.piece em { margin-left: auto; font-style: normal; font-size: 10px; font-weight: 700; color: var(--orange); }
.wood-count { display: flex; align-items: center; gap: 7px; font-family: 'Rajdhani', sans-serif; }
.wood-icon { width: 13px; height: 13px; background: linear-gradient(135deg, #b8864b, #7d5426); box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.3); }
.wood-count strong { font-size: 18px; font-weight: 700; color: #f2efe6; line-height: 1; }
.wood-count small { font-size: 8px; font-weight: 700; letter-spacing: 0.2em; color: #7f8987; }

/* bottom */
.hud-bottom {
  position: absolute; left: 18px; right: 18px; bottom: calc(14px + var(--safe));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px;
}
.vitals {
  width: 310px; padding: 11px 13px 9px;
  background: linear-gradient(180deg, rgba(7, 10, 11, 0.5), rgba(7, 10, 11, 0.78));
  border: 1px solid var(--line-soft);
  border-left: 2px solid var(--orange);
  backdrop-filter: blur(8px);
}
.vital-row { display: grid; grid-template-columns: 18px 1fr 36px; align-items: center; gap: 8px; margin-bottom: 6px; }
.vital-icon { width: 15px; height: 15px; position: relative; opacity: 0.85; }
.vital-icon.health::before { content: ''; position: absolute; inset: 3px; background: #f2efe6; clip-path: polygon(50% 100%, 0 45%, 0 18%, 25% 0, 50% 18%, 75% 0, 100% 18%, 100% 45%); }
.vital-icon.armor::before { content: ''; position: absolute; inset: 2px 3px; background: #9fc6e8; clip-path: polygon(50% 0, 100% 18%, 100% 62%, 50% 100%, 0 62%, 0 18%); }
.vital-track { height: 8px; background: rgba(255, 255, 255, 0.09); overflow: hidden; position: relative; }
.vital-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #d8d5cc, #f5f2e9); transition: width 0.25s ease; }
.armor-row .vital-track { height: 5px; }
.armor-row .vital-track i { background: linear-gradient(90deg, #5b8db8, #9fc6e8); width: 0%; }
.vital-row strong { font-family: 'Barlow Condensed', sans-serif; font-size: 19px; font-weight: 700; line-height: 1; text-align: right; color: #f0ede4; font-variant-numeric: tabular-nums; }
.armor-row strong { font-size: 14px; color: #a9c8e2; }
.vital-sub { display: flex; align-items: center; justify-content: space-between; margin-top: 3px; font-size: 9px; font-weight: 700; letter-spacing: 0.13em; color: #8b9492; }
.vital-sub span { display: flex; align-items: center; gap: 5px; }
.vital-sub b { color: #d8d4ca; font-size: 11px; }
.vital-sub kbd { font-size: 8px; padding: 2px 4px 1px; }
.chip.med { width: 10px; height: 10px; background: #d8d4ca; clip-path: polygon(35% 0, 65% 0, 65% 35%, 100% 35%, 100% 65%, 65% 65%, 65% 100%, 35% 100%, 35% 65%, 0 65%, 0 35%, 35% 35%); }
.mode-tag { color: #6d7775; }
.mode-tag.crouch { color: var(--orange); }

.weapon-panel {
  display: grid;
  grid-template-columns: auto auto;
  grid-template-areas: 'name ammo' 'slots slots';
  align-items: end; gap: 2px 16px;
  padding: 9px 14px 10px;
  min-width: 280px;
  background: linear-gradient(180deg, rgba(7, 10, 11, 0.5), rgba(7, 10, 11, 0.8));
  border: 1px solid var(--line-soft);
  backdrop-filter: blur(8px);
  position: relative;
}
.weapon-name { grid-area: name; display: flex; flex-direction: column; gap: 2px; }
.weapon-name span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 23px; letter-spacing: 0.08em; line-height: 1; color: #f2efe6; }
.weapon-name small { font-size: 8px; font-weight: 700; letter-spacing: 0.22em; color: var(--orange); }
.ammo { grid-area: ammo; display: flex; align-items: baseline; gap: 4px; font-family: 'Barlow Condensed', sans-serif; }
.ammo strong { font-size: 44px; font-weight: 700; line-height: 0.85; color: #f5f2e9; font-variant-numeric: tabular-nums; }
.ammo span { color: #5e6866; font-size: 18px; }
.ammo em { font-style: normal; font-size: 17px; font-weight: 600; color: #8d9694; }
.ammo.low strong { color: var(--orange); }
.weapon-slots { grid-area: slots; display: flex; gap: 6px; margin-top: 6px; }
.slot { flex: 1; display: flex; align-items: center; gap: 7px; padding: 4px 7px; border: 1px solid var(--line-soft); background: rgba(255, 255, 255, 0.025); font-size: 9px; font-weight: 700; letter-spacing: 0.12em; color: #89928f; min-height: 23px; }
.slot b { color: #666f6d; font-size: 9px; }
.slot.active { border-color: rgba(255, 122, 24, 0.45); background: rgba(255, 122, 24, 0.1); color: #e3ded4; }
.slot.active b { color: var(--orange); }
.slot span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.reload-hint { position: absolute; left: 14px; top: -19px; font-size: 9px; font-weight: 700; letter-spacing: 0.14em; color: #cdd2ca; opacity: 0; transition: opacity 0.2s; }
.reload-hint.show { opacity: 1; animation: blink 1.1s step-end infinite; }

.minimap-wrap { position: relative; width: 182px; height: 182px; background: #07100d; border: 1px solid rgba(255, 255, 255, 0.16); box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4); }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: -1px; border: 1px solid rgba(255, 122, 24, 0.35); pointer-events: none; }
.minimap-ring::before, .minimap-ring::after { content: ''; position: absolute; width: 9px; height: 9px; border: 1px solid var(--orange); }
.minimap-ring::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.minimap-ring::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }
.minimap-label { position: absolute; bottom: 3px; right: 5px; font-size: 8px; font-weight: 700; letter-spacing: 0.16em; color: rgba(255, 255, 255, 0.42); }

#toast {
  position: absolute; left: 50%; top: 125px; transform: translate(-50%, -8px);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 18px; letter-spacing: 0.24em;
  color: #f5f2e9; text-align: center; opacity: 0; transition: opacity 0.3s, transform 0.3s;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.8);
  pointer-events: none;
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast small { font-family: 'Rajdhani', sans-serif; font-size: 10px; letter-spacing: 0.2em; color: var(--orange); font-weight: 700; }

#damageNumbers { position: absolute; inset: 0; overflow: hidden; }
.dmg-num { position: absolute; transform: translate(-50%, -50%); font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 19px; color: #fff; text-shadow: 0 2px 6px rgba(0, 0, 0, 0.9); animation: dmgFloat 0.75s ease-out forwards; white-space: nowrap; }
.dmg-num.head { color: #ffd257; font-size: 24px; }
.dmg-num.kill { color: #ff6a55; font-size: 22px; }

/* ============================================================
   TOUCH
   ============================================================ */
#touch { position: absolute; inset: 0; z-index: 22; display: none; pointer-events: none; }
body.touch #touch { display: block; }
body.touch #touch.hidden { display: none; }
.touch-zone { position: absolute; pointer-events: auto; }
#stickZone { left: 0; bottom: 0; width: 46%; height: 62%; }
