function addLoot(world, x, z, kind) {
  world.addLootPoint(x, world.getHeight(x, z) + 0.07, z, kind)
}

function seeded(seed) {
  let a = seed >>> 0
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

import { clamp } from './utils.js'

const ACTION_KEYS = {
  KeyR: 'reload',
  KeyE: 'interact',
  KeyF: 'harvest',
  KeyH: 'heal',
  KeyQ: 'build',
  KeyM: 'mute',
  Digit1: 'slot1',
  Digit2: 'slot2',
  Digit3: 'slot3',
  Space: 'jump'
}

export class Input {
  constructor(canvas) {
    this.canvas = canvas
    this.keys = new Set()
    this.pressed = new Set()
    this.lookX = 0
    this.lookY = 0
    this.fireHeld = false
    this.aimHeld = false
    this.aimTouch = false
    this.crouchTouch = false
    this.sprintTouch = false
    this.stick = { x: 0, z: 0 }
    this.enabled = false
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
    this.pointerLocked = false
    this.hadLock = false
    this.sensitivity = 1
    this.onPauseRequest = null
    this.onPointerLockChange = null
    this.muteRequested = false
    this._bind()
    if (this.isTouch) document.body.classList.add('touch')
  }

  _bind() {
    window.addEventListener('keydown', (e) => {
      if (!this.enabled) return
      if (e.code === 'Tab') e.preventDefault()
      if (e.code === 'Escape') {
        this.pressed.add('escape')
        return
      }
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault()
      if (!this.keys.has(e.code)) {
        const action = ACTION_KEYS[e.code]
        if (action) this.pressed.add(action)
        if (e.code === 'KeyC' || e.code === 'ControlLeft') this.pressed.add('crouchToggle')
      }
      this.keys.add(e.code)
    })
    window.addEventListener('keyup', (e) => this.keys.delete(e.code))
    window.addEventListener('blur', () => {
      this.keys.clear()
      this.fireHeld = false
      this.aimHeld = false
    })

    document.addEventListener('mousemove', (e) => {
      if (!this.enabled) return
      if (this.pointerLocked) {
        this.lookX += e.movementX || 0
        this.lookY += e.movementY || 0
      }
    })
    this.canvas.addEventListener('mousedown', (e) => {
      if (!this.enabled) return
      if (e.button === 0) this.fireHeld = true
      if (e.button === 2) this.aimHeld = true
    })
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.fireHeld = false
      if (e.button === 2) this.aimHeld = false
    })
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault())
    this.canvas.addEventListener('wheel', (e) => {
      if (!this.enabled) return
      this.pressed.add(e.deltaY > 0 ? 'slot2' : 'slot1')
    }, { passive: true })

    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas
      if (this.pointerLocked) this.hadLock = true
      if (!this.pointerLocked && this.hadLock && this.enabled && !this.isTouch && this.onPointerLockChange) {
        this.onPointerLockChange()
      }
    })

    if (this.isTouch) this._bindTouch()
  }

  _bindTouch() {
    const stickZone = document.getElementById('stickZone')
    const stickBase = document.getElementById('stickBase')
    const knob = document.getElementById('stickKnob')
    const lookZone = document.getElementById('lookZone')
    if (!stickZone) return
    let stickId = null
    let stickCenter = null
    const maxDistance = 44

    const updateStick = (e) => {
      const dx = e.clientX - stickCenter.x
      const dy = e.clientY - stickCenter.y
      const len = Math.hypot(dx, dy)
      const limited = Math.min(len, maxDistance)
      const nx = len > 0 ? (dx / len) * (limited / maxDistance) : 0
      const ny = len > 0 ? (dy / len) * (limited / maxDistance) : 0
      this.stick.x = nx
      this.stick.z = -ny
      this.sprintTouch = Math.hypot(nx, ny) > 0.94
      knob.style.transform = `translate(${nx * maxDistance}px, ${ny * maxDistance}px)`
    }

    stickZone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      stickId = e.pointerId
      const rect = stickBase.getBoundingClientRect()
      stickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }
      stickZone.setPointerCapture(e.pointerId)
      updateStick(e)
    })
    stickZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== stickId) return
      updateStick(e)
    })
    const endStick = (e) => {
      if (e.pointerId !== stickId) return
      stickId = null
      this.stick.x = 0
      this.stick.z = 0
      this.sprintTouch = false
      knob.style.transform = 'translate(0, 0)'
    }
    stickZone.addEventListener('pointerup', endStick)
    stickZone.addEventListener('pointercancel', endStick)

    let lookId = null
    let lastX = 0
    let lastY = 0
    lookZone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      lookId = e.pointerId
      lastX = e.clientX
      lastY = e.clientY
      lookZone.setPointerCapture(e.pointerId)
    })
    lookZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookId) return
      this.lookX += (e.clientX - lastX) * 1.35
      this.lookY += (e.clientY - lastY) * 1.35
      lastX = e.clientX
      lastY = e.clientY
    })
    const endLook = (e) => { if (e.pointerId === lookId) lookId = null }
    lookZone.addEventListener('pointerup', endLook)
    lookZone.addEventListener('pointercancel', endLook)

    document.querySelectorAll('.tbtn').forEach((btn) => {
      const act = btn.dataset.act
      const down = (e) => {
        e.preventDefault()
        if (!this.enabled) return
        btn.classList.add('on')
        if (act === 'fire') {
          this.fireHeld = true
        } else if (act === 'aim') {
          this.aimTouch = !this.aimTouch
          btn.classList.toggle('on', this.aimTouch)
        } else if (act === 'crouch') {
          this.crouchTouch = !this.crouchTouch
          btn.classList.toggle('on', this.crouchTouch)
          this.pressed.add('crouchToggle')
        } else {
          this.pressed.add(act)
          if (act === 'build') this.pressed.add('build')
        }
      }
      const up = (e) => {
        e.preventDefault()
        if (act === 'fire') {
          this.fireHeld = false
          btn.classList.remove('on')
        } else if (act !== 'aim' && act !== 'crouch') {
          btn.classList.remove('on')
        }
      }
      btn.addEventListener('pointerdown', down)
      btn.addEventListener('pointerup', up)
      btn.addEventListener('pointercancel', up)
      btn.addEventListener('pointerleave', up)
    })
  }

  get moving() {
    return Math.hypot(this.moveX, this.moveZ) > 0.08
  }

  get moveX() {
    let x = 0
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1
    if (this.isTouch) x += this.stick.x
    return clamp(x, -1, 1)
  }

  get moveZ() {
    let z = 0
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) z += 1
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) z -= 1
    if (this.isTouch) z += this.stick.z
    return clamp(z, -1, 1)
  }

  get sprint() {
    return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.sprintTouch
  }

  get crouch() {
    return this.keys.has('ControlLeft') || this.keys.has('KeyC') || this.crouchTouch
  }

  get firing() {
    return this.fireHeld
  }

  get aiming() {
    return this.aimHeld || this.aimTouch
  }

  consume(action) {
    if (this.pressed.has(action)) {
      this.pressed.delete(action)
      return true
    }
    return false
  }

  endFrame() {
    this.pressed.clear()
    this.lookX = 0
    this.lookY = 0
  }

  lock() {
    if (this.isTouch) return
    try {
      const result = this.canvas.requestPointerLock()
      if (result && typeof result.catch === 'function') result.catch(() => {})
    } catch {
      /* pointer lock is best-effort */
    }
  }

  unlock() {
    if (document.pointerLockElement) document.exitPointerLock()
  }

  reset() {
    this.keys.clear()
    this.pressed.clear()
    this.lookX = 0
    this.lookY = 0
    this.fireHeld = false
    this.aimHeld = false
    this.aimTouch = false
    this.crouchTouch = false
    this.stick.x = 0
    this.stick.z = 0
  }
}

// Procedural WebAudio sound design — no asset downloads.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.enabled = true
    this.noiseBuffer = null
    this.ambient = null
    this.zoneHum = null
    this.lastBotShot = 0
    this.shotCount = 0
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.enabled ? 0.7 : 0
    const limiter = this.ctx.createDynamicsCompressor()
    limiter.threshold.value = -12
    limiter.knee.value = 18
    limiter.ratio.value = 8
    limiter.attack.value = 0.003
    limiter.release.value = 0.22
    this.master.connect(limiter)
    limiter.connect(this.ctx.destination)
    this._buildNoise()
    this._startAmbient()
  }

  setEnabled(on) {
    this.enabled = on
    if (this.master) {
      this.master.gain.setTargetAtTime(on ? 0.7 : 0, this.ctx.currentTime, 0.05)
    }
    if (on) this.init()
  }

  _buildNoise() {
    const len = this.ctx.sampleRate * 2
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    this.noiseBuffer = buffer
  }

  _startAmbient() {
    const ctx = this.ctx
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 380
    filter.Q.value = 0.6
    const gain = ctx.createGain()
    gain.gain.value = 0.045
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    src.start()
    this.ambient = { src, gain, filter }

    // A very low drone that rises when the zone is dangerous.
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.value = 42
    const humGain = ctx.createGain()
    humGain.gain.value = 0
    osc.connect(humGain)
    humGain.connect(this.master)
    osc.start()
    this.zoneHum = { osc, gain: humGain }
    this._ambientTime = 0
  }

  _pan(pan = 0) {
    if (!this.ctx.createStereoPanner) return null
    const p = this.ctx.createStereoPanner()
    p.pan.value = Math.max(-1, Math.min(1, pan))
    return p
  }

  _route(node, volume, pan) {
    const gain = this.ctx.createGain()
    gain.gain.value = volume
    const panner = this._pan(pan)
    if (panner) {
      node.connect(gain)
      gain.connect(panner)
      panner.connect(this.master)
    } else {
      node.connect(gain)
      gain.connect(this.master)
    }
    return gain
  }

  gun(type = 'm416', volume = 1, distance = 0, pan = 0) {
    if (!this.ctx || !this.enabled) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const profile = {
      p92: { dur: 0.14, freq: 1600, thump: 140, gain: 0.55, tail: 0.1 },
      ump45: { dur: 0.16, freq: 1300, thump: 120, gain: 0.6, tail: 0.12 },
      m416: { dur: 0.19, freq: 1050, thump: 95, gain: 0.7, tail: 0.16 },
      s686: { dur: 0.34, freq: 620, thump: 65, gain: 1.0, tail: 0.28 },
      kar98: { dur: 0.5, freq: 520, thump: 52, gain: 1.05, tail: 0.45 }
    }[type] || { dur: 0.2, freq: 900, thump: 90, gain: 0.7, tail: 0.15 }
    const distGain = distance > 0 ? Math.max(0.025, 1 - distance / 210) : 1
    const vol = Math.max(0, Math.min(1.4, volume * profile.gain * distGain))
    if (vol < 0.012) return
    if (distance > 0 && this.shotCount > 0 && now - this.lastBotShot < 0.035) return
    this.lastBotShot = now
    this.shotCount++

    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 0.9 + Math.random() * 0.2
    const band = ctx.createBiquadFilter()
    band.type = 'bandpass'
    band.frequency.value = profile.freq
    band.Q.value = 0.7
    const low = ctx.createBiquadFilter()
    low.type = 'lowpass'
    low.frequency.value = 5200
    const env = ctx.createGain()
    env.gain.setValueAtTime(0, now)
    env.gain.linearRampToValueAtTime(vol, now + 0.004)
    env.gain.exponentialRampToValueAtTime(0.001, now + profile.dur)
    src.connect(band)
    band.connect(low)
    low.connect(env)
    const panner = this._pan(pan)
    if (panner) {
      env.connect(panner)
      panner.connect(this.master)
    } else env.connect(this.master)
    src.start(now)
    src.stop(now + profile.dur + 0.02)

    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(profile.thump, now)
    osc.frequency.exponentialRampToValueAtTime(profile.thump * 0.55, now + profile.dur * 0.7)
    const og = ctx.createGain()
    og.gain.setValueAtTime(vol * 0.8, now)
    og.gain.exponentialRampToValueAtTime(0.001, now + profile.tail)
    osc.connect(og)
    const op = this._pan(pan)
    if (op) {
      og.connect(op)
      op.connect(this.master)
    } else og.connect(this.master)
    osc.start(now)
    osc.stop(now + profile.tail + 0.02)
  }

  click(freq = 900, dur = 0.04, volume = 0.15) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    osc.type = 'square'
    osc.frequency.value = freq
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(volume, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur)
    osc.connect(g)
    g.connect(this.master)
    osc.start(now)
    osc.stop(now + dur + 0.01)
  }

  reloadStart() {
    this.click(320, 0.06, 0.18)
    this.click(210, 0.05, 0.12)
  }

  reloadEnd() {
    this.click(680, 0.05, 0.2)
    setTimeout(() => this.click(430, 0.05, 0.15), 55)
  }

  dryFire() {
    this.click(1100, 0.03, 0.12)
  }

  hit(headshot = false) {
    this.click(headshot ? 1900 : 1400, 0.035, headshot ? 0.16 : 0.12)
  }

  kill() {
    this.click(720, 0.09, 0.14)
    setTimeout(() => this.click(1080, 0.12, 0.12), 55)
  }

  hurt() {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 320
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.4, now)
    g.gain.exponentialRampToValueAtTime(0.001, now + 0.2)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(now)
    src.stop(now + 0.22)
  }

  pickup() {
    this.click(880, 0.06, 0.1)
    setTimeout(() => this.click(1320, 0.09, 0.1), 60)
  }

  build() {
    this.click(190, 0.12, 0.2)
    setTimeout(() => this.click(120, 0.1, 0.12), 70)
  }

  destroy() {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = 420
    filter.Q.value = 0.5
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.4, now)
    g.gain.exponentialRampToValueAtTime(0.001, now + 0.35)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(now)
    src.stop(now + 0.36)
  }

  chop() {
    this.click(240, 0.06, 0.2)
    this.click(160, 0.1, 0.15)
  }

  heal() {
    this.click(620, 0.2, 0.07)
    setTimeout(() => this.click(780, 0.25, 0.06), 150)
  }

  footstep(volume = 0.09) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 0.7 + Math.random() * 0.4
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 700
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(volume, now)
    g.gain.exponentialRampToValueAtTime(0.001, now + 0.09)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(now)
    src.stop(now + 0.1)
  }

  zone(on) {
    if (!this.zoneHum || !this.ctx) return
    this.zoneHum.gain.gain.setTargetAtTime(on ? 0.05 : 0, this.ctx.currentTime, 0.6)
  }

  update(dt, outside, danger) {
    if (!this.ctx || !this.zoneHum) return
    const target = outside ? 0.06 : 0
    this.zoneHum.gain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.35)
    this.zoneHum.osc.frequency.setTargetAtTime(38 + danger * 14, this.ctx.currentTime, 0.4)
  }
}

import * as THREE from 'three'

const MAX_SPARKS = 320
const MAX_DUST = 160
const MAX_DECALS = 70

export class FX {
  constructor(scene, textures, quality = 'high') {
    this.scene = scene
    this.textures = textures
    this.tracers = []
    this.decals = []
    this.flashes = []
    this.time = 0
    this.quality = quality

    this.sparks = this._makeParticles(MAX_SPARKS, 0.075, true)
    this.dust = this._makeParticles(MAX_DUST, 0.4, false)

    this.flashPool = []
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.SpriteMaterial({
        map: textures.muzzle,
        color: 0xffd08a,
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: true
      })
      const sprite = new THREE.Sprite(mat)
      sprite.visible = false
      sprite.renderOrder = 3
      scene.add(sprite)
      this.flashPool.push({ sprite, life: 0 })
    }

    this.flashLight = new THREE.PointLight(0xffb060, 0, 16, 2)
    this.flashLight.visible = false
    scene.add(this.flashLight)

    this.decalGeo = new THREE.PlaneGeometry(0.26, 0.26)
    this.decalMat = new THREE.MeshBasicMaterial({
      map: textures.hole,
      transparent: true,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -4,
      polygonOffsetUnits: -4
    })
  }

  _makeParticles(max, size, additive) {
    const geometry = new THREE.BufferGeometry()
    const positions = new Float32Array(max * 3)
    const colors = new Float32Array(max * 3)
    for (let i = 0; i < max; i++) positions[i * 3 + 1] = -999
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    const material = new THREE.PointsMaterial({
      size,
      map: this.textures.soft,
      vertexColors: true,
      transparent: true,
      opacity: additive ? 0.9 : 0.35,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      sizeAttenuation: true
    })
    const points = new THREE.Points(geometry, material)
    points.frustumCulled = false
    this.scene.add(points)
    return {
      points,
      geometry,
      positions,
      colors,
      data: Array.from({ length: max }, () => ({ vx: 0, vy: 0, vz: 0, life: 0, max: 1, r: 1, g: 1, b: 1, size: 1 })),
      cursor: 0,
      max
    }
  }

  _spawn(store, x, y, z, vx, vy, vz, life, color, spread = 1) {
    const i = store.cursor
    store.cursor = (store.cursor + 1) % store.max
    const d = store.data[i]
    d.vx = vx
    d.vy = vy
    d.vz = vz
    d.life = life
    d.max = life
    d.r = color.r
    d.g = color.g
    d.b = color.b
    store.positions[i * 3] = x
    store.positions[i * 3 + 1] = y
    store.positions[i * 3 + 2] = z
    store.colors[i * 3] = color.r
    store.colors[i * 3 + 1] = color.g
    store.colors[i * 3 + 2] = color.b
  }

  sparkBurst(position, count = 8, color = 0xffb060, speed = 6, life = 0.4) {
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2
      const b = Math.random() * Math.PI - Math.PI / 2
      const s = speed * (0.3 + Math.random() * 0.9)
      this._spawn(this.sparks, position.x, position.y, position.z,
        Math.cos(a) * Math.cos(b) * s, Math.abs(Math.sin(b)) * s + 1.5, Math.sin(a) * Math.cos(b) * s,
        life * (0.5 + Math.random()), c)
    }
  }

  dustPuff(position, normal, color = 0xb6aa90, count = 4) {
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const s = 0.7 + Math.random() * 1.2
      this._spawn(this.dust, position.x + normal.x * 0.1, position.y + normal.y * 0.1, position.z + normal.z * 0.1,
        normal.x * s + (Math.random() - 0.5) * 1.2,
        normal.y * s + Math.random() * 1.0,
        normal.z * s + (Math.random() - 0.5) * 1.2,
        0.5 + Math.random() * 0.5, c)
    }
  }

  tracer(from, to, color = 0xffd08a, opacity = 0.85) {
    const geo = new THREE.BufferGeometry().setFromPoints([from, to])
    const mat = new THREE.LineBasicMaterial({
      color,
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    })
    const line = new THREE.Line(geo, mat)
    line.frustumCulled = false
    this.scene.add(line)
    this.tracers.push({ line, life: 0.08 + Math.random() * 0.03 })
  }

  impact(point, normal, kind = 'terrain') {
    this.dustPuff(point, normal, kind === 'terrain' ? 0xb9ac8a : 0xb9b4a6, kind === 'terrain' ? 5 : 3)
    this.sparkBurst(point, kind === 'build' || kind === 'metal' ? 9 : 4, 0xffc070, 5, 0.3)
    if (kind !== 'water' && this.decals.length < MAX_DECALS) {
      const mesh = new THREE.Mesh(this.decalGeo, this.decalMat)
      mesh.position.copy(point).addScaledVector(normal, 0.02)
      mesh.lookAt(point.clone().add(normal))
      mesh.rotateZ(Math.random() * Math.PI * 2)
      mesh.renderOrder = 1
      this.scene.add(mesh)
      this.decals.push({ mesh, life: 26 })
    }
  }

  muzzle(position, scale = 0.55, color = 0xffd08a) {
    const entry = this.flashPool.find((f) => f.life <= 0) || this.flashPool[0]
    entry.sprite.position.copy(position)
    entry.sprite.scale.set(scale, scale, 1)
    entry.sprite.material.rotation = Math.random() * Math.PI
    entry.sprite.material.color.set(color)
    entry.sprite.material.opacity = 0.95
    entry.sprite.visible = true
    entry.life = 0.055
    return entry
  }

  playerFlash(position, direction) {
    this.muzzle(position, 0.6)
    this.flashLight.position.copy(position)
    this.flashLight.intensity = 9
    this.flashLight.visible = true
    const d = direction || new THREE.Vector3(0, 0, -1)
    this.flashLight.position.addScaledVector(d, 0.4)
    this._flashDecay = 0.05
  }

  debris(position, color = 0x9c7a4a, count = 14) {
    this.sparkBurst(position, count, color, 5.5, 0.55)
    this.dustPuff(position, new THREE.Vector3(0, 1, 0), 0xb2a184, 8)
  }

  update(dt) {
    this.time += dt
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i]
      t.life -= dt
      t.line.material.opacity = Math.max(0, t.life / 0.1) * 0.85
      if (t.life <= 0) {
        this.scene.remove(t.line)
        t.line.geometry.dispose()
        t.line.material.dispose()
        this.tracers.splice(i, 1)
      }
    }
    for (const store of [this.sparks, this.dust]) {
      let changed = false
      for (let i = 0; i < store.max; i++) {
        const d = store.data[i]
        if (d.life <= 0) continue
        d.life -= dt
        const idx = i * 3
        if (d.life <= 0) {
          store.positions[idx + 1] = -999
          changed = true
          continue
        }
        const drag = store === this.dust ? 0.035 : 0.012
        d.vx -= d.vx * drag
        d.vy -= (store === this.dust ? 2.5 : 12) * dt
        d.vz -= d.vz * drag
        store.positions[idx] += d.vx * dt
        store.positions[idx + 1] += d.vy * dt
        store.positions[idx + 2] += d.vz * dt
        const fade = d.life / d.max
        store.colors[idx] = d.r * fade
        store.colors[idx + 1] = d.g * fade
        store.colors[idx + 2] = d.b * fade
        changed = true
      }
      if (changed) {
        store.geometry.attributes.position.needsUpdate = true
        store.geometry.attributes.color.needsUpdate = true
      }
    }
    for (let i = this.flashPool.length - 1; i >= 0; i--) {
      const f = this.flashPool[i]
      if (f.life > 0) {
        f.life -= dt
        f.sprite.material.opacity = Math.max(0, f.life / 0.055)
        if (f.life <= 0) f.sprite.visible = false
      }
    }
    if (this.flashLight.visible) {
      this.flashLight.intensity *= Math.pow(0.0001, dt)
      if (this.flashLight.intensity < 0.2) {
        this.flashLight.intensity = 0
        this.flashLight.visible = false
      }
    }
    for (let i = this.decals.length - 1; i >= 0; i--) {
      const d = this.decals[i]
      d.life -= dt
      if (d.life <= 0) {
        this.scene.remove(d.mesh)
        this.decals.splice(i, 1)
      }
    }
  }
}

import * as THREE from 'three'
import { WEAPONS, LOOT_WEIGHTS, RARITY } from './config.js'
import { makeLootLabel } from './textures.js'
import { weightedPick, mulberry32, clamp } from './utils.js'

export class LootSystem {
  constructor(scene, world, textures) {
    this.scene = scene
    this.world = world
    this.textures = textures
    this.items = []
    this.rng = mulberry32((Date.now() ^ 0x9e37) >>> 0)
    this.time = 0
    this.root = new THREE.Group()
    this.root.name = 'loot'
    this.scene.add(this.root)

    this.crateGeo = new THREE.BoxGeometry(0.52, 0.5, 0.52)
    this.bandGeo = new THREE.BoxGeometry(0.56, 0.08, 0.56)
    this.beamGeo = new THREE.CylinderGeometry(0.17, 0.17, 2.2, 8, 1, true)
    this.crateMatBase = new THREE.MeshStandardMaterial({
      map: textures.crate,
      color: 0x9c8766,
      roughness: 0.85,
      metalness: 0.08
    })

    for (const point of world.lootPoints) this.add(point)
  }

  pickWeapon() {
    return weightedPick(this.rng, LOOT_WEIGHTS).id
  }

  add(point) {
    const kind = point.kind
    const weaponId = point.weapon || (kind === 'weapon' ? this.pickWeapon() : null)
    const rarity = weaponId ? (RARITY[weaponId] || RARITY.ammo) : (RARITY[kind] || RARITY.ammo)
    const name = weaponId ? WEAPONS[weaponId].name : kind === 'ammo' ? 'AMMO' : kind === 'medkit' ? 'MEDKIT' : kind === 'armor' ? 'ARMOR' : 'SUPPLY'
    const color = new THREE.Color(rarity.color)

    const group = new THREE.Group()
    group.position.set(point.x, point.y, point.z)

    const crateMat = this.crateMatBase.clone()
    crateMat.color.copy(color).multiplyScalar(0.42).add(new THREE.Color(0x5b513f))
    const crate = new THREE.Mesh(this.crateGeo, crateMat)
    crate.position.y = 0.27
    crate.rotation.y = Math.random() * Math.PI
    crate.castShadow = true
    crate.receiveShadow = true
    group.add(crate)

    const bandMat = new THREE.MeshStandardMaterial({
      color: color.clone(),
      emissive: color.clone().multiplyScalar(0.8),
      emissiveIntensity: 1.2,
      roughness: 0.4,
      metalness: 0.2
    })
    const band = new THREE.Mesh(this.bandGeo, bandMat)
    band.position.y = 0.5
    band.rotation.y = crate.rotation.y
    group.add(band)

    const beamMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.16,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide
    })
    const beam = new THREE.Mesh(this.beamGeo, beamMat)
    beam.position.y = 1.35
    group.add(beam)

    const labelTexture = makeLootLabel(name, rarity.label, rarity.color)
    const labelMat = new THREE.SpriteMaterial({
      map: labelTexture,
      transparent: true,
      depthWrite: false,
      depthTest: true,
      opacity: 0.95
    })
    const label = new THREE.Sprite(labelMat)
    label.position.y = 1.78
    label.scale.set(1.42, 0.71, 1)
    group.add(label)

    this.root.add(group)
    const item = {
      point: { ...point, weapon: weaponId },
      group, crate, band, beam, label, color,
      baseY: point.y,
      name, kind, weaponId,
      taken: false,
      phase: Math.random() * Math.PI * 2
    }
    this.items.push(item)
    return item
  }

  addWeapon(x, y, z, weaponId) {
    return this.add({ x, y, z, kind: 'weapon', weapon: weaponId })
  }

  nearest(position, range = 3.1) {
    let best = null
    let bestDist = range
    for (const item of this.items) {
      if (item.taken) continue
      const dx = position.x - item.group.position.x
      const dz = position.z - item.group.position.z
      const dy = Math.abs(position.y + 0.6 - item.group.position.y)
      if (dy > 2.6) continue
      const d = Math.hypot(dx, dz)
      if (d < bestDist) {
        bestDist = d
        best = item
      }
    }
    return best ? { item: best, distance: bestDist } : null
  }

  take(item) {
    if (item.taken) return
    item.taken = true
    item.group.visible = false
    item.group.traverse((o) => {
      if (o.isMesh) {
        if (o.material && o.material !== this.crateMatBase) {
          if (o.material.map && o.material.map !== this.textures.crate) o.material.map.dispose()
          o.material.dispose()
        }
      }
    })
    setTimeout(() => this.root.remove(item.group), 0)
  }

  getWeaponLabel(weaponId) {
    return WEAPONS[weaponId]?.name || 'WEAPON'
  }

  update(dt, camera, playerPos) {
    this.time += dt
    const t = this.time
    for (const item of this.items) {
      if (item.taken) continue
      const g = item.group
      const dist = playerPos ? Math.hypot(playerPos.x - g.position.x, playerPos.z - g.position.z) : 0
      g.visible = dist < 95
      if (!g.visible) continue
      const bob = Math.sin(t * 1.8 + item.phase) * 0.06
      item.crate.position.y = 0.27 + bob
      item.band.position.y = 0.5 + bob
      item.crate.rotation.y += dt * 0.5
      item.band.rotation.y = item.crate.rotation.y
      item.beam.material.opacity = 0.10 + Math.sin(t * 2.4 + item.phase) * 0.045
      item.beam.scale.y = 1 + Math.sin(t * 1.6 + item.phase) * 0.07
      item.label.visible = dist < 28
      if (item.label.visible) {
        item.label.position.y = 1.78 + bob * 0.7
        item.label.material.opacity = clamp(1 - (dist - 18) / 12, 0.1, 0.95)
      }
    }
  }
}

import * as THREE from 'three'
import { ZONE_PHASES, ZONE_START_RADIUS } from './config.js'
import { clamp, lerp, formatTime } from './utils.js'

export class Zone {
  constructor(scene, audio) {
    this.scene = scene
    this.audio = audio
    this.active = false
    this.center = { x: 0, z: 0 }
    this.fromCenter = { x: 0, z: 0 }
    this.targetCenter = { x: 0, z: 0 }
    this.radius = ZONE_START_RADIUS
    this.fromRadius = ZONE_START_RADIUS
    this.targetRadius = ZONE_START_RADIUS
    this.phaseIndex = 0
    this.state = 'wait'
    this.timer = ZONE_PHASES[0].wait
    this.duration = 0
    this.dps = ZONE_PHASES[0].dps
    this.final = false
    this.time = 0
    this._buildMesh()
    this._buildInner()
  }

  _buildMesh() {
    const uniforms = {
      uTime: { value: 0 },
      uOpacity: { value: 0.5 },
      uDanger: { value: 0 }
    }
    const geo = new THREE.CylinderGeometry(1, 1, 1, 96, 1, true)
    const mat = new THREE.ShaderMaterial({
      uniforms,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.NormalBlending,
      vertexShader: /* glsl */`
        varying vec2 vUv;
        varying vec3 vWorld;
        void main() {
          vUv = uv;
          vec4 world = modelMatrix * vec4(position, 1.0);
          vWorld = world.xyz;
          gl_Position = projectionMatrix * viewMatrix * world;
        }
      `,
      fragmentShader: /* glsl */`
        uniform float uTime;
        uniform float uOpacity;
        uniform float uDanger;
        varying vec2 vUv;
        varying vec3 vWorld;

        void main() {
          float stripes = smoothstep(0.955, 1.0, fract(vUv.x * 130.0));
          float bands = smoothstep(0.92, 1.0, fract(vUv.y * 18.0 - uTime * 0.6));
          float verticalFade = smoothstep(0.0, 0.06, vUv.y) * smoothstep(1.0, 0.9, vUv.y);
          float topGlow = smoothstep(0.94, 1.0, vUv.y) * 0.35;
          vec3 base = mix(vec3(0.12, 0.45, 0.95), vec3(0.55, 0.9, 1.0), uDanger);
          vec3 col = mix(base, vec3(0.72, 0.95, 1.0), stripes * 0.8 + bands * 0.4);
          float alpha = (0.055 + stripes * 0.105 + bands * 0.03 + topGlow) * uOpacity * verticalFade * 1.5;
          gl_FragColor = vec4(col, alpha);
        }
      `
    })
    this.mesh = new THREE.Mesh(geo, mat)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 2
    this.mesh.visible = false
    this.scene.add(this.mesh)
    this.uniforms = uniforms
    this.material = mat
  }

  _buildInner() {
    // Faint inner shell gives the wall depth when you are close.
    const geo = new THREE.CylinderGeometry(1, 1, 1, 96, 1, true)
    const mat = new THREE.MeshBasicMaterial({
      color: 0x4fa8ff,
      transparent: true,
      opacity: 0.028,
      side: THREE.DoubleSide,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    })
    this.inner = new THREE.Mesh(geo, mat)
    this.inner.frustumCulled = false
    this.inner.visible = false
    this.inner.renderOrder = 1
    this.scene.add(this.inner)
  }

  reset() {
    this.phaseIndex = 0
    this.state = 'wait'
    this.timer = ZONE_PHASES[0].wait
    this.duration = 0
    this.radius = ZONE_START_RADIUS
    this.fromRadius = this.radius
    this.targetRadius = this.radius
    this.center = { x: 0, z: 0 }
    this.fromCenter = { ...this.center }
    this.targetCenter = { ...this.center }
    this.dps = ZONE_PHASES[0].dps
    this.final = false
    this.active = false
    this.time = 0
    this._sync(0)
  }

  start() {
    this.active = true
    this.mesh.visible = true
    this.inner.visible = true
    this.audio?.zone(false)
  }

  startShrink() {
    const phase = ZONE_PHASES[this.phaseIndex]
    this.fromRadius = this.radius
    this.targetRadius = phase.radius
    this.fromCenter = { ...this.center }
    const maxOffset = Math.max(0, this.radius - phase.radius) * 0.62
    const a = Math.random() * Math.PI * 2
    const dist = Math.sqrt(Math.random()) * maxOffset
    this.targetCenter = {
      x: this.center.x + Math.cos(a) * dist,
      z: this.center.z + Math.sin(a) * dist
    }
    this.state = 'shrink'
    this.duration = phase.shrink
    this.timer = phase.shrink
    this.dps = phase.dps
    this.audio?.zone(true)
  }

  update(dt) {
    if (!this.active) return
    this.time += dt
    this.uniforms.uTime.value = this.time
    if (this.timer !== Infinity) this.timer -= dt
    if (this.state === 'wait' && this.timer <= 0) {
      this.startShrink()
    } else if (this.state === 'shrink') {
      const t = clamp(1 - this.timer / this.duration, 0, 1)
      this.radius = lerp(this.fromRadius, this.targetRadius, t)
      this.center.x = lerp(this.fromCenter.x, this.targetCenter.x, t)
      this.center.z = lerp(this.fromCenter.z, this.targetCenter.z, t)
      if (this.timer <= 0) {
        this.radius = this.targetRadius
        this.center = { ...this.targetCenter }
        this.phaseIndex++
        if (this.phaseIndex >= ZONE_PHASES.length) {
          this.state = 'final'
          this.final = true
          this.timer = Infinity
          this.dps = ZONE_PHASES[ZONE_PHASES.length - 1].dps
        } else {
          this.state = 'wait'
          this.timer = ZONE_PHASES[this.phaseIndex].wait
          this.dps = ZONE_PHASES[this.phaseIndex].dps
        }
      }
    }
    this._sync(dt)
  }

  _sync(dt) {
    const h = 140
    this.mesh.position.set(this.center.x, h / 2, this.center.z)
    this.mesh.scale.set(this.radius, h, this.radius)
    this.inner.position.set(this.center.x, h / 2, this.center.z)
    this.inner.scale.set(this.radius * 0.997, h, this.radius * 0.997)
    const danger = clamp(this.phaseIndex / (ZONE_PHASES.length - 1), 0, 1)
    this.uniforms.uDanger.value = danger
    this.uniforms.uOpacity.value = 0.55 + danger * 0.35
    this.inner.material.opacity = 0.02 + danger * 0.02
  }

  outside(x, z) {
    const dx = x - this.center.x
    const dz = z - this.center.z
    return dx * dx + dz * dz > this.radius * this.radius
  }

  distanceInside(x, z) {
    return this.radius - Math.hypot(x - this.center.x, z - this.center.z)
  }

  damagePerSecond() {
    return this.dps
  }

  get phaseLabel() {
    if (this.final) return 'FINAL ZONE'
    if (this.state === 'shrink') return 'ZONE CLOSING'
    return 'ZONE CLOSING SOON'
  }

  get countdown() {
    if (this.final) return 'FINAL'
    return formatTime(Math.max(0, this.timer))
  }

  get nextRadius() {
    if (this.final) return this.radius
    if (this.state === 'shrink') return this.targetRadius
    return ZONE_PHASES[this.phaseIndex]?.radius ?? this.radius
  }

  get nextCenter() {
    if (this.final) return this.center
    if (this.state === 'shrink') return this.targetCenter
    return this.center
  }

  get danger() {
    return clamp(this.phaseIndex / (ZONE_PHASES.length - 1), 0, 1)
  }
}

import * as THREE from 'three'
import { BUILD_COSTS, BUILD_MAX_HP, MATCH } from './config.js'
import { clamp } from './utils.js'

const SNAP = MATCH.buildGrid

export class Building {
  constructor(scene, world, player, hud, audio, fx) {
    this.scene = scene
    this.world = world
    this.player = player
    this.hud = hud
    this.audio = audio
    this.fx = fx
    this.active = false
    this.piece = 'wall'
    this.structures = []
    this.maxStructures = 44
    this.rotation = 0
    this.valid = false
    this.target = new THREE.Vector3()
    this.baseY = 0
    this.ghosts = {}
    this._buildGhosts()
    this._buildMaterials()
    this._geoCache = {}
  }

  _buildMaterials() {
    const tex = this.world.textures
    const woodMap = tex.wood.clone()
    woodMap.needsUpdate = true
    woodMap.repeat.set(2, 2)
    this.woodMat = new THREE.MeshStandardMaterial({ map: woodMap, color: 0xc39a63, roughness: 0.88 })
    this.woodDarkMat = new THREE.MeshStandardMaterial({ map: tex.wood, color: 0x6c4f31, roughness: 0.9 })
    this.metalMat = new THREE.MeshStandardMaterial({ map: tex.metal, color: 0x8b9296, metalness: 0.55, roughness: 0.55 })
    this.ghostValid = new THREE.MeshBasicMaterial({ color: 0x62ff9a, transparent: true, opacity: 0.28, depthWrite: false, side: THREE.DoubleSide })
    this.ghostInvalid = new THREE.MeshBasicMaterial({ color: 0xff5a48, transparent: true, opacity: 0.3, depthWrite: false, side: THREE.DoubleSide })
    this.ghostLineValid = new THREE.LineBasicMaterial({ color: 0x8dffb8, transparent: true, opacity: 0.75 })
    this.ghostLineInvalid = new THREE.LineBasicMaterial({ color: 0xff7a68, transparent: true, opacity: 0.8 })
  }

  _buildGhosts() {
    const specs = {
      wall: { w: 4, h: 3, d: 0.2, y: 1.5 },
      floor: { w: 4, h: 0.18, d: 4, y: 0.09 },
      ramp: { w: 4, h: 0.16, d: 5, y: 1.5, rx: Math.atan2(3, 4) }
    }
    for (const [key, spec] of Object.entries(specs)) {
      const group = new THREE.Group()
      const geo = new THREE.BoxGeometry(spec.w, spec.h, spec.d)
      const mesh = new THREE.Mesh(geo, this.ghostValid)
      if (spec.rx) mesh.rotation.x = spec.rx
      const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), this.ghostLineValid)
      if (spec.rx) edges.rotation.x = spec.rx
      group.add(mesh, edges)
      group.visible = false
      group.renderOrder = 5
      this.scene.add(group)
      this.ghosts[key] = { group, mesh, edges, spec, y: spec.y }
    }
  }

  setActive(active) {
    this.active = active
    if (!active) for (const g of Object.values(this.ghosts)) g.group.visible = false
  }

  setPiece(piece) {
    if (!this.ghosts[piece]) return
    this.piece = piece
    for (const [key, g] of Object.entries(this.ghosts)) g.group.visible = false
    this.ghosts[piece].group.visible = true
  }

  rotate() {
    this.rotation = (this.rotation + Math.PI / 2) % (Math.PI * 2)
  }

  update(dt) {
    if (!this.active) return
    const p = this.player
    const yaw = Math.round(p.yaw / (Math.PI / 2)) * (Math.PI / 2)
    this.rotation = yaw
    const fwdX = -Math.sin(p.yaw)
    const fwdZ = -Math.cos(p.yaw)
    const reach = this.piece === 'floor' ? 4.0 : 4.3
    let tx = p.pos.x + fwdX * reach
    let tz = p.pos.z + fwdZ * reach
    tx = Math.round(tx / SNAP) * SNAP
    tz = Math.round(tz / SNAP) * SNAP
    const ground = this.world.getHeight(tx, tz)
    let baseY = Math.max(p.pos.y, ground)
    baseY = Math.round(baseY * 20) / 20
    this.target.set(tx, 0, tz)
    this.baseY = baseY
    const ghost = this.ghosts[this.piece]
    ghost.group.position.set(tx, baseY, tz)
    ghost.group.rotation.y = yaw
    this.valid = this._validate(tx, tz, baseY, yaw)
    ghost.mesh.material = this.valid ? this.ghostValid : this.ghostInvalid
    ghost.edges.material = this.valid ? this.ghostLineValid : this.ghostLineInvalid
  }

  _validate(tx, tz, baseY, yaw) {
    if (this.structures.length >= this.maxStructures) return false
    if (this.world.getHeight(tx, tz) < 0.35) return false
    if (this.world.distance2D ? false : false) return false
    if (Math.hypot(tx - this.player.pos.x, tz - this.player.pos.z) > MATCH.buildRange + 2.5) return false
    if (this.player.wood < BUILD_COSTS[this.piece]) return false
    const box = this._boundsFor(tx, tz, baseY, yaw, this.piece)
    for (const s of this.structures) {
      if (s.hp <= 0) continue
      if (intersects(box, s.bounds, 0.15)) return false
    }
    // Do not build inside solid world geometry.
    for (const ob of this.world.obstacles) {
      if (ob.kind !== 'static' || ob.maxY - ob.minY < 1.4) continue
      if (intersects(box, ob, 0.05)) return false
    }
    return true
  }

  _boundsFor(tx, tz, baseY, yaw, piece) {
    if (piece === 'wall') {
      const along = Math.abs(Math.cos(yaw)) > 0.5
      const hw = along ? 2 : 0.16
      const hd = along ? 0.16 : 2
      return { minX: tx - hw, maxX: tx + hw, minY: baseY - 0.05, maxY: baseY + 3.1, minZ: tz - hd, maxZ: tz + hd }
    }
    if (piece === 'floor') {
      return { minX: tx - 2, maxX: tx + 2, minY: baseY - 0.05, maxY: baseY + 0.24, minZ: tz - 2, maxZ: tz + 2 }
    }
    return { minX: tx - 2, maxX: tx + 2, minY: baseY - 0.05, maxY: baseY + 3.1, minZ: tz - 2.5, maxZ: tz + 2.5 }
  }

  place() {
    if (!this.active) return false
    const p = this.player
    if (!this.valid) {
      this.hud?.toast(p.wood < BUILD_COSTS[this.piece] ? 'NOT ENOUGH WOOD' : 'CANNOT BUILD HERE', 'FIND FLAT OPEN GROUND', 1.6)
      this.audio?.click(180, 0.05, 0.08)
      return false
    }
    const cost = BUILD_COSTS[this.piece]
    p.wood -= cost
    const yaw = Math.round(p.yaw / (Math.PI / 2)) * (Math.PI / 2)
    const tx = this.target.x
    const tz = this.target.z
    const baseY = this.baseY
    const group = new THREE.Group()
    group.position.set(tx, baseY, tz)
    group.rotation.y = yaw
    const structure = {
      piece: this.piece,
      group,
      hp: BUILD_MAX_HP,
      maxHp: BUILD_MAX_HP,
      bounds: this._boundsFor(tx, tz, baseY, yaw, this.piece),
      materials: [],
      obstacles: [],
      platforms: [],
      flash: 0,
      dead: false
    }
    if (this.piece === 'wall') this._buildWall(group, structure)
    else if (this.piece === 'floor') this._buildFloor(group, structure)
    else this._buildRamp(group, structure)
    group.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = true
        o.receiveShadow = true
      }
    })
    this.scene.add(group)
    this.structures.push(structure)
    this._registerPhysics(structure)
    this.audio?.build()
    this.fx?.dustPuff(new THREE.Vector3(tx, baseY + 0.2, tz), new THREE.Vector3(0, 1, 0), 0xb39a72, 8)
    this.valid = false
    return true
  }

  _registerPhysics(structure) {
    const b = structure.bounds
    if (structure.piece !== 'ramp') {
      structure.obstacles.push(this.world.addDynamicObstacle(
        { minX: b.minX, maxX: b.maxX, minY: b.minY, maxY: b.maxY, minZ: b.minZ, maxZ: b.maxZ },
        structure
      ))
    }
    if (structure.piece === 'floor') {
      structure.platforms.push(this.world.addDynamicPlatform({
        minX: b.minX, maxX: b.maxX, minZ: b.minZ, maxZ: b.maxZ, y: b.maxY
      }, structure))
    }
    if (structure.piece === 'ramp') {
      // Six invisible steps make the ramp walkable without a slope physics solver.
      const along = Math.abs(Math.cos(structure.group.rotation.y)) > 0.5
      for (let i = 0; i < 6; i++) {
        const t = (i + 0.5) / 6
        const y = b.minY + t * 3.0
        const zOff = (0.5 - t) * 4
        const x = along ? structure.group.position.x : structure.group.position.x + zOff
        const z = along ? structure.group.position.z + zOff : structure.group.position.z
        structure.platforms.push(this.world.addDynamicPlatform({
          minX: x - (along ? 1.9 : 0.5),
          maxX: x + (along ? 1.9 : 0.5),
          minZ: z - (along ? 0.5 : 1.9),
          maxZ: z + (along ? 0.5 : 1.9),
          y
        }, structure))
      }
    }
  }

  _buildWall(group, structure) {
    const mat = this.woodMat.clone()
    const trimMat = this.woodDarkMat.clone()
    structure.materials.push(mat, trimMat)
    const panel = new THREE.Mesh(new THREE.BoxGeometry(4, 3, 0.18), mat)
    panel.position.y = 1.5
    group.add(panel)
    for (const x of [-1.88, 1.88]) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.2, 3.2, 0.26), trimMat)
      post.position.set(x, 1.6, 0)
      group.add(post)
    }
    const top = new THREE.Mesh(new THREE.BoxGeometry(4.15, 0.2, 0.3), trimMat)
    top.position.y = 3.05
    group.add(top)
    const bottom = new THREE.Mesh(new THREE.BoxGeometry(4.15, 0.18, 0.28), trimMat)
    bottom.position.y = 0.14
    group.add(bottom)
    for (const sign of [-1, 1]) {
      const brace = new THREE.Mesh(new THREE.BoxGeometry(4.0, 0.14, 0.3), trimMat)
      brace.position.set(0, 1.55, 0.005)
      brace.rotation.z = sign * 0.62
      group.add(brace)
    }
    const plate = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.3, 0.06), this.metalMat)
    plate.position.set(0, 1.6, 0.12)
    group.add(plate)
  }

  _buildFloor(group, structure) {
    const mat = this.woodMat.clone()
    const trimMat = this.woodDarkMat.clone()
    structure.materials.push(mat, trimMat)
    const deck = new THREE.Mesh(new THREE.BoxGeometry(4, 0.18, 4), mat)
    deck.position.y = 0.09
    group.add(deck)
    for (const z of [-1.5, 0, 1.5]) {
      const beam = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.18, 0.22), trimMat)
      beam.position.set(0, -0.05, z)
      group.add(beam)
    }
    for (const x of [-2.02, 2.02]) {
      const edge = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.28, 4.1), trimMat)
      edge.position.set(x, 0.1, 0)
      group.add(edge)
    }
  }

  _buildRamp(group, structure) {
    const mat = this.woodMat.clone()
    const trimMat = this.woodDarkMat.clone()
    structure.materials.push(mat, trimMat)
    const angle = Math.atan2(3, 4)
    const ramp = new THREE.Mesh(new THREE.BoxGeometry(4, 0.18, 5.1), mat)
    ramp.position.y = 1.5
    ramp.rotation.x = angle
    group.add(ramp)
    for (const x of [-2.0, 2.0]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.14, 1.1, 5.1), trimMat)
      rail.position.set(x, 2.35, 0)
      rail.rotation.x = angle
      group.add(rail)
    }
    for (let i = 0; i < 6; i++) {
      const t = (i + 0.5) / 6
      const brace = new THREE.Mesh(new THREE.BoxGeometry(3.9, 0.14, 0.16), trimMat)
      brace.position.set(0, t * 3 + 0.1, (0.5 - t) * 4)
      group.add(brace)
    }
  }

  damage(structure, amount) {
    if (!structure || structure.dead) return
    structure.hp -= amount
    structure.flash = 0.12
    if (structure.hp <= 0) this._destroy(structure)
  }

  _destroy(structure) {
    structure.dead = true
    structure.hp = 0
    const pos = structure.group.position
    this.fx?.debris(new THREE.Vector3(pos.x, pos.y + 1.3, pos.z), 0xa07c4c, 20)
    this.audio?.destroy()
    for (const entry of structure.obstacles) this.world.removeDynamicObstacle(entry)
    for (const entry of structure.platforms) this.world.removeDynamicPlatform(entry)
    this.scene.remove(structure.group)
    structure.group.traverse((o) => {
      if (o.isMesh) {
        if (o.geometry && !this._geoCache[o.geometry.uuid]) { o.geometry.dispose() }
      }
    })
    structure.materials.forEach((m) => m.dispose())
    const idx = this.structures.indexOf(structure)
    if (idx >= 0) this.structures.splice(idx, 1)
    if (this.hud) this.hud.toast('COVER DESTROYED', 'BUILD ANOTHER', 1.2)
  }

  updateDamage(dt) {
    for (const s of this.structures) {
      if (s.flash > 0) {
        s.flash -= dt
        const v = clamp(s.flash / 0.12, 0, 1)
        for (const m of s.materials) {
          m.emissive = m.emissive || new THREE.Color(0, 0, 0)
          m.emissive.setRGB(v * 0.8, v * 0.18, 0)
        }
      }
    }
  }
}

function intersects(a, b, pad = 0) {
  return a.maxX > b.minX - pad && a.minX < b.maxX + pad &&
    a.maxY > b.minY - pad && a.minY < b.maxY + pad &&
    a.maxZ > b.minZ - pad && a.minZ < b.maxZ + pad
}

import * as THREE from 'three'

const UP = new THREE.Vector3(0, 1, 0)
const Q = new THREE.Quaternion()
const V = new THREE.Vector3()

const PALETTE = {
  gunmetal: { color: 0x25292c, metalness: 0.82, roughness: 0.34 },
  polymer: { color: 0x34383a, metalness: 0.05, roughness: 0.78 },
  tan: { color: 0x8d7a58, metalness: 0.08, roughness: 0.7 },
  wood: { color: 0x5e4329, metalness: 0.02, roughness: 0.72 },
  glove: { color: 0x2b2d29, metalness: 0.02, roughness: 0.96 },
  sleeve: { color: 0x4c5341, metalness: 0.01, roughness: 0.98 },
  skin: { color: 0xb08360, metalness: 0.0, roughness: 0.9 },
  lens: { color: 0x2f6c86, metalness: 0.5, roughness: 0.12, emissive: 0x0b2430 },
  accent: { color: 0xc8641f, metalness: 0.4, roughness: 0.4 }
}

function box(parent, mat, w, h, d, x, y, z, rx = 0, ry = 0, rz = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
  mesh.position.set(x, y, z)
  mesh.rotation.set(rx, ry, rz)
  parent.add(mesh)
  return mesh
}

function cyl(parent, mat, radius, length, x, y, z, axis = 'z') {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, length, 12), mat)
  mesh.position.set(x, y, z)
  if (axis === 'z') mesh.rotation.x = Math.PI / 2
  parent.add(mesh)
  return mesh
}

function limb(parent, sleeveMat, gloveMat, from, to, thickness = 0.085) {
  const a = new THREE.Vector3(...from)
  const b = new THREE.Vector3(...to)
  const dir = b.clone().sub(a)
  const len = dir.length()
  const geo = new THREE.BoxGeometry(thickness, len, thickness * 1.05)
  const mesh = new THREE.Mesh(geo, sleeveMat)
  mesh.position.copy(a).add(b).multiplyScalar(0.5)
  Q.setFromUnitVectors(UP, dir.normalize())
  mesh.quaternion.copy(Q)
  parent.add(mesh)
  const hand = new THREE.Mesh(new THREE.BoxGeometry(thickness * 1.25, 0.11, 0.16), gloveMat)
  hand.position.copy(b)
  hand.rotation.set(0.3, 0, 0)
  parent.add(hand)
  return mesh
}

export class Viewmodel {
