    limb(g, m.sleeve, m.glove, [0.27, -0.62, 0.16], [0.045, -0.14, 0.03], 0.095)
    limb(g, m.sleeve, m.glove, [-0.3, -0.64, 0.08], [-0.07, -0.17, 0.08], 0.09)
