    box(g, m.gunmetal, 0.012, 0.03, 0.03, 0, 0.055, -0.66)
    box(g, m.wood, 0.08, 0.16, 0.09, 0, -0.12, 0.14, 0.24, 0, 0)
    box(g, m.accent, 0.098, 0.016, 0.1, 0, -0.045, -0.22)
    limb(g, m.sleeve, m.glove, [0.28, -0.62, 0.18], [0.05, -0.15, 0.06], 0.1)
