431:   scatterTrees() {
432:     const rng = mulberry32(4411)
433:     const pineTrunks = []
434:     const pineCanopy = []
435:     const broadTrunks = []
436:     const broadCanopy = []
437:     let attempts = 0
438:     const target = this.quality === 'low' ? 190 : this.quality === 'medium' ? 260 : 320
439:     while (this.trees.length < target && attempts < target * 30) {
440:       attempts++
441:       const a = rng() * TAU
442:       const r = Math.sqrt(rng()) * 322
443:       const x = Math.cos(a) * r
444:       const z = Math.sin(a) * r
445:       const h = this.getHeight(x, z)
446:       if (h < 2.2 || h > 74) continue
447:       if (this.getSlope(x, z) > 0.86) continue
448:       if (this.nearSite(x, z, 6)) continue
449:       if (this.nearRoad(x, z, 4)) continue
450:       if (this.nearLake(x, z, 8)) continue
451:       let close = false
452:       for (const t of this.trees) {
453:         if (Math.hypot(t.x - x, t.z - z) < 4.4) { close = true; break }
454:       }
455:       if (close) continue
456:       const pine = rng() > 0.42
457:       const scale = 0.75 + rng() * 0.75
458:       const rot = rng() * TAU
459:       const tree = { x, z, y: h, scale, pine, rot }
460:       this.trees.push(tree)
