486:         m.compose(
487:           new THREE.Vector3(t.x, t.y - 0.1, t.z),
488:           new THREE.Quaternion().setFromEuler(new THREE.Euler(0, t.rot, 0)),
489:           new THREE.Vector3(t.scale * 0.9, height, t.scale * 0.9)
