748:   resolveCircle(pos, radius, height) {
749:     const feet = pos.y
750:     const head = pos.y + height
751:     const lists = [this.obstacles, this.dynamicObstacles]
752:     for (let pass = 0; pass < 2; pass++) {
753:       for (const list of lists) {
754:         for (const box of list) {
755:           if (box.maxY <= feet + 0.03 || box.minY >= head - 0.03) continue
756:           const nearestX = clamp(pos.x, box.minX, box.maxX)
757:           const nearestZ = clamp(pos.z, box.minZ, box.maxZ)
758:           let dx = pos.x - nearestX
759:           let dz = pos.z - nearestZ
760:           const d2 = dx * dx + dz * dz
761:           if (d2 >= radius * radius) continue
762:           if (d2 < 1e-8) {
763:             const left = pos.x - box.minX
764:             const right = box.maxX - pos.x
765:             const back = pos.z - box.minZ
766:             const front = box.maxZ - pos.z
767:             const min = Math.min(left, right, back, front)
768:             if (min === left) pos.x = box.minX - radius
769:             else if (min === right) pos.x = box.maxX + radius
770:             else if (min === back) pos.z = box.minZ - radius
771:             else pos.z = box.maxZ + radius
772:           } else {
773:             const d = Math.sqrt(d2)
774:             const push = (radius - d) / d
775:             pos.x += dx * push
776:             pos.z += dz * push
777:           }
778:         }
779:       }
780:     }
781:   }
