801:   raycast(origin, dir, maxDist = 300) {
802:     let best = { distance: maxDist, point: null, normal: new THREE.Vector3(0, 1, 0), kind: 'none', box: null }
803:     // Terrain (march + bisect)
804:     const step = 0.6
805:     let prevT = 0.2
806:     let prevH = this.getHeight(origin.x + dir.x * prevT, origin.z + dir.z * prevT)
807:     let prevY = origin.y + dir.y * prevT
808:     for (let t = step; t <= Math.min(maxDist, 360); t += step) {
809:       const x = origin.x + dir.x * t
810:       const z = origin.z + dir.z * t
811:       const y = origin.y + dir.y * t
812:       const h = this.getHeight(x, z)
813:       if (y <= h) {
814:         let lo = prevT
815:         let hi = t
816:         for (let k = 0; k < 7; k++) {
817:           const mid = (lo + hi) / 2
818:           const mx = origin.x + dir.x * mid
819:           const mz = origin.z + dir.z * mid
820:           const my = origin.y + dir.y * mid
821:           if (my <= this.getHeight(mx, mz)) hi = mid
822:           else lo = mid
823:         }
824:         const px = origin.x + dir.x * hi
825:         const pz = origin.z + dir.z * hi
826:         const py = origin.y + dir.y * hi
827:         const gradX = this.getHeight(px + 0.6, pz) - this.getHeight(px - 0.6, pz)
828:         const gradZ = this.getHeight(px, pz + 0.6) - this.getHeight(px, pz - 0.6)
829:         const normal = new THREE.Vector3(-gradX, 1.2, -gradZ).normalize()
830:         best = { distance: hi, point: new THREE.Vector3(px, py, pz), normal, kind: 'terrain', box: null }
831:         break
832:       }
833:       prevT = t
834:       prevH = h
835:       prevY = y
836:     }
837:     // Water surface
838:     if (origin.y > 0 && dir.y < -1e-4) {
839:       const tw = -origin.y / dir.y
840:       if (tw > 0.05 && tw < best.distance) {
841:         best = {
842:           distance: tw,
843:           point: new THREE.Vector3(origin.x + dir.x * tw, 0, origin.z + dir.z * tw),
844:           normal: new THREE.Vector3(0, 1, 0),
845:           kind: 'water',
846:           box: null
847:         }
848:       }
849:     }
850:     // Boxes
851:     const checkList = (list, dynamic) => {
852:       for (const box of list) {
853:         const t = rayAABB(origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, box, best.distance)
854:         if (t !== null && t < best.distance) {
855:           const point = new THREE.Vector3(origin.x + dir.x * t, origin.y + dir.y * t, origin.z + dir.z * t)
856:           best = { distance: t, point, normal: boxNormal(box, point), kind: dynamic ? 'build' : box.kind, box }
857:         }
858:       }
859:     }
860:     checkList(this.obstacles, false)
861:     checkList(this.dynamicObstacles, true)
862:     return best
863:   }
