865:   hasLineOfSight(ax, ay, az, bx, by, bz) {
866:     const dx = bx - ax
867:     const dy = by - ay
868:     const dz = bz - az
869:     const len = Math.hypot(dx, dy, dz)
870:     if (len < 0.2) return true
871:     const hit = this.raycast({ x: ax, y: ay, z: az }, { x: dx / len, y: dy / len, z: dz / len }, len - 0.35)
872:     return hit.distance >= len - 0.4
873:   }
