import * as THREE from 'three'
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js'

const UP = new THREE.Vector3(0, 1, 0)
const MAT = new THREE.Matrix4()
const Q = new THREE.Quaternion()
const E = new THREE.Euler()
const V = new THREE.Vector3()

const MATERIAL_DEFS = {
  concrete: { map: 'concrete', color: 0xd9d5c8, roughness: 0.94 },
  concreteDark: { map: 'concrete', color: 0x9d9a8f, roughness: 0.96 },
  foundation: { map: 'concrete', color: 0x7c7a70, roughness: 1 },
  plaster: { map: 'plaster', color: 0xe0d8c5, roughness: 0.92 },
  plasterWarm: { map: 'plaster', color: 0xd7bf99, roughness: 0.92 },
  plasterBlue: { map: 'plaster', color: 0xa9b9b4, roughness: 0.92 },
  wood: { map: 'wood', color: 0xb28a58, roughness: 0.88 },
  woodDark: { map: 'wood', color: 0x745536, roughness: 0.9 },
  woodPale: { map: 'wood', color: 0xc9ad7d, roughness: 0.88 },
  metal: { map: 'metal', color: 0xb2babe, metalness: 0.5, roughness: 0.52 },
  metalBlue: { map: 'metal', color: 0x78909c, metalness: 0.45, roughness: 0.55 },
  rust: { map: 'metal', color: 0x9b6544, metalness: 0.32, roughness: 0.8 },
  darkMetal: { color: 0x3d4347, metalness: 0.62, roughness: 0.48 },
  roof: { map: 'roof', color: 0x8b8f8e, roughness: 0.82 },
  roofRust: { map: 'roof', color: 0x9b7654, roughness: 0.86 },
  trim: { map: 'wood', color: 0x4a3927, roughness: 0.9 },
  trimPale: { color: 0xd9d2c0, roughness: 0.8 },
  glass: { color: 0xa8cfdd, transparent: true, opacity: 0.24, metalness: 0.65, roughness: 0.08, depthWrite: false },
  glassDark: { color: 0x1d2c33, transparent: true, opacity: 0.62, metalness: 0.7, roughness: 0.14, depthWrite: false },
  crate: { map: 'crate', color: 0xb69a6c, roughness: 0.9 },
  sandbag: { map: 'sandbag', color: 0xcdbd8e, roughness: 1 },
  fabric: { map: 'sandbag', color: 0x66714b, roughness: 1 },
  fabricTan: { map: 'sandbag', color: 0xa89465, roughness: 1 },
  asphalt: { map: 'asphalt', color: 0xffffff, roughness: 0.96 },
  orange: { color: 0xc85c1e, roughness: 0.72, metalness: 0.12 },
  white: { color: 0xe4e0d4, roughness: 0.82 },
  rock: { color: 0x8e8c82, roughness: 0.98, flatShading: true },
  green: { color: 0x52603d, roughness: 0.94 },
  gablePlaster: { map: 'plaster', color: 0xded6c3, roughness: 0.92, side: THREE.DoubleSide },
  gableWood: { map: 'wood', color: 0xa27c4f, roughness: 0.9, side: THREE.DoubleSide },
  gableMetal: { map: 'metal', color: 0xa4adb2, metalness: 0.45, roughness: 0.55, side: THREE.DoubleSide }
}

export class Builder {
  constructor(textures, world) {
    this.textures = textures
    this.world = world
    this.batches = new Map()
    this.materials = {}
    this.geometryCount = 0
    this.boxGeo = new THREE.BoxGeometry(1, 1, 1)
    this.crateGeo = new THREE.BoxGeometry(1, 1, 1)
  }

  getMaterial(key) {
    if (this.materials[key]) return this.materials[key]
    const def = MATERIAL_DEFS[key] || MATERIAL_DEFS.concrete
    const params = { color: def.color, roughness: def.roughness ?? 0.9, metalness: def.metalness ?? 0 }
    if (def.map) {
      const source = this.textures[def.map]
      const tex = source.clone()
      tex.needsUpdate = true
      params.map = tex
    }
    if (def.transparent) {
      params.transparent = true
      params.opacity = def.opacity ?? 0.5
    }
    if (def.depthWrite === false) params.depthWrite = false
    if (def.side) params.side = def.side
    if (def.flatShading) params.flatShading = true
    const mat = new THREE.MeshStandardMaterial(params)
    mat.name = key
    this.materials[key] = mat
    return mat
  }

  push(key, geo) {
    if (!this.batches.has(key)) this.batches.set(key, [])
    this.batches.get(key).push(geo)
    this.geometryCount++
  }

  _collider(key, geo, opts, matrix) {
    if (opts.collide === false) return
    geo.computeBoundingBox()
    const box = geo.boundingBox.clone()
    // A tiny skin prevents z-fighting with ground contact.
    box.min.y -= 0.02
    this.world.addObstacle(box, key)
    if (opts.platform) {
      this.world.addPlatform({ minX: box.min.x, maxX: box.max.x, minZ: box.min.z, maxZ: box.max.z, y: box.max.y })
    }
  }

  box(key, w, h, d, x, y, z, opts = {}) {
    const geo = new THREE.BoxGeometry(w, h, d)
    E.set(opts.rx || 0, opts.ry || 0, opts.rz || 0, 'YXZ')
    Q.setFromEuler(E)
    MAT.compose(V.set(x, y, z), Q, new THREE.Vector3(1, 1, 1))
    geo.applyMatrix4(MAT)
    this.push(key, geo)
    this._collider(key, geo, opts)
    return geo
  }

  cylinder(key, radiusTop, radiusBottom, height, x, y, z, opts = {}) {
    const geo = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, opts.segments || 10, 1, opts.open || false)
    E.set(opts.rx || 0, opts.ry || 0, opts.rz || 0, 'YXZ')
    Q.setFromEuler(E)
    MAT.compose(V.set(x, y, z), Q, new THREE.Vector3(1, 1, 1))
    geo.applyMatrix4(MAT)
    this.push(key, geo)
    this._collider(key, geo, opts)
    return geo
  }

  // A beam between two world points.
  beam(key, a, b, thickness = 0.16, opts = {}) {
    const start = new THREE.Vector3(...a)
    const end = new THREE.Vector3(...b)
    const dir = end.clone().sub(start)
    const len = dir.length()
    const geo = new THREE.BoxGeometry(thickness, len, opts.depth || thickness)
    Q.setFromUnitVectors(UP, dir.normalize())
    const mid = start.clone().add(end).multiplyScalar(0.5)
    MAT.compose(mid, Q, new THREE.Vector3(1, 1, 1))
    geo.applyMatrix4(MAT)
    this.push(key, geo)
    if (opts.collide) this._collider(key, geo, opts)
    // Open doors
    this.lbox(key, ctx, 0.1, h - 0.1, d - 0.3, w / 2 + 1.0, ctx.baseY + h / 2 + 0.12, d / 2, { ry: 0.7, collide: false })
    this.lbox(key, ctx, 0.1, h - 0.1, d - 0.3, -w / 2 - 1.0, ctx.baseY + h / 2 + 0.12, d / 2, { ry: -0.7, collide: false })
    this.addLoot(ctx, 0, 0, ctx.baseY + 0.14, 'weapon')
    return ctx
  }

  sandbagWall(x, z, rot, length = 6, rows = 3) {
    const baseY = this.world.getHeight(x, z)
    const bagW = 0.9
    const bagH = 0.32
    const bagD = 0.55
    const count = Math.max(2, Math.round(length / bagW))
    for (let r = 0; r < rows; r++) {
      for (let i = 0; i < count; i++) {
        const lx = -length / 2 + bagW / 2 + i * bagW
        const off = r % 2 === 0 ? 0 : bagW * 0.25
        const lz = off
        const p = this.local({ x, z, rot }, lx, lz)
        this.box('sandbag', bagW - 0.04, bagH, bagD, p.x, baseY + bagH / 2 + r * bagH, p.z, { ry: rot, collide: false })
      }
    }
    this.box('sandbag', length, rows * bagH, bagD, x, baseY + (rows * bagH) / 2, z, { ry: rot, collide: true })
    return baseY
  }

  crate(ctx, lx, lz, floorY, size = 1.0, stacked = false) {
    const p = this.local(ctx, lx, lz)
    this.box('crate', size, size, size, p.x, floorY + size / 2, p.z, { ry: ctx.rot + 0.1, collide: true })
    this.box('trim', size + 0.02, 0.08, size + 0.02, p.x, floorY + size * 0.95, p.z, { ry: ctx.rot + 0.1, collide: false })
    if (stacked) this.box('crate', size * 0.75, size * 0.75, size * 0.75, p.x + 0.1, floorY + size + size * 0.36, p.z, { ry: ctx.rot - 0.2, collide: true })
  }

  barrel(x, z, y) {
    const h = this.world.getHeight(x, z)
    const base = y ?? h
    this.cylinder('rust', 0.36, 0.36, 0.95, x, base + 0.48, z, { segments: 10, collide: true })
    this.cylinder('darkMetal', 0.38, 0.38, 0.06, x, base + 0.28, z, { segments: 10, collide: false })
    this.cylinder('darkMetal', 0.38, 0.38, 0.06, x, base + 0.74, z, { segments: 10, collide: false })
  }

  vehicle(o) {
    const ctx = { x: o.x, z: o.z, rot: o.rot || 0, baseY: this.world.getHeight(o.x, o.z) }
    const key = o.key || 'rust'
    // Body
    this.lbox(key, ctx, 4.6, 0.8, 2.0, 0, ctx.baseY + 0.75, 0, { collide: true })
    this.lbox(key, ctx, 2.6, 0.85, 1.9, -0.2, ctx.baseY + 1.5, 0, { collide: true })
    this.lbox('glassDark', ctx, 2.2, 0.5, 1.7, -0.2, ctx.baseY + 1.75, 0, { collide: false })
    this.lbox('trim', ctx, 1.0, 0.5, 1.8, 2.0, ctx.baseY + 1.0, 0, { collide: false })
    for (const [lx, lz] of [[-1.4, -0.95], [1.4, -0.95], [-1.4, 0.95], [1.4, 0.95]]) {
      const p = this.local(ctx, lx, lz)
      this.box('darkMetal', 0.62, 0.62, 0.3, p.x, ctx.baseY + 0.38, p.z, { ry: ctx.rot, collide: false })
    }
    this.lbox('darkMetal', ctx, 4.7, 0.16, 0.2, 0, ctx.baseY + 0.45, 1.02, { collide: false })
    return ctx
  }

  fence(x, z, rot, length, height = 1.35) {
    const baseY = this.world.getHeight(x, z)
    const posts = Math.max(2, Math.round(length / 3))
    for (let i = 0; i <= posts; i++) {
      const lx = -length / 2 + (length / posts) * i
      const p = this.local({ x, z, rot }, lx, 0)
      this.box('woodDark', 0.14, height, 0.14, p.x, baseY + height / 2, p.z, { ry: rot, collide: false })
    }
    const p = this.local({ x, z, rot }, 0, 0)
    for (const yy of [height * 0.45, height * 0.85]) {
      this.box('woodDark', length, 0.1, 0.08, p.x, baseY + yy, p.z, { ry: rot, collide: false })
    }
    this.box('woodDark', length, height, 0.08, p.x, baseY + height / 2, p.z, { ry: rot, collide: true })
  }

  dock(x, z, rot, length = 14, width = 3.6) {
    const baseY = this.world.getHeight(x, z)
    const y = Math.max(1.1, baseY + 0.35)
    const steps = Math.max(2, Math.round((y - baseY) / 0.28))
    for (let i = 0; i < steps; i++) {
      const p = this.local({ x, z, rot }, 0, -length / 2 - 0.4 - i * 0.5)
      this.box('wood', width, 0.18, 0.5, p.x, baseY + 0.14 + i * 0.18, p.z, { ry: rot, collide: false, platform: true })
    }
    const p = this.local({ x, z, rot }, 0, 0)
    this.box('wood', width, 0.16, length, p.x, y, p.z, { ry: rot, collide: true, platform: true })
    for (let i = 0; i < 5; i++) {
      for (const sx of [-1, 1]) {
        const pp = this.local({ x, z, rot }, (sx * width) / 2, -length / 2 + 1 + i * (length / 4))
        this.cylinder('woodDark', 0.14, 0.14, y + 1.2, pp.x, (y + 1.2) / 2 - 0.6, pp.z, { segments: 6, collide: false })
      }
    }
    // Railings
    for (const sx of [-1, 1]) {
      const pp = this.local({ x, z, rot }, (sx * width) / 2, 0)
      this.box('woodDark', 0.08, 0.9, length, pp.x, y + 0.55, pp.z, { ry: rot, collide: false })
    }
    return y
  }

  helipad(x, z) {
    const y = this.world.getHeight(x, z) + 0.06
    this.disk('concreteDark', 11, x, y, z, { segments: 36 })
    this.ring('white', 9.6, 10.0, x, y + 0.02, z, { segments: 40 })
    this.ring('orange', 8.6, 8.8, x, y + 0.02, z, { segments: 40 })
    // H marking
    const p1 = this.local({ x, z, rot: 0 }, -1.9, 0)
    const p2 = this.local({ x, z, rot: 0 }, 1.9, 0)
    this.box('white', 0.65, 0.03, 4.6, p1.x, y + 0.03, p1.z, { collide: false })
    this.box('white', 0.65, 0.03, 4.6, p2.x, y + 0.03, p2.z, { collide: false })
    this.box('white', 3.8, 0.03, 0.6, x, y + 0.03, z, { collide: false })
  }

  powerPole(x, z) {
    const baseY = this.world.getHeight(x, z)
    this.cylinder('woodDark', 0.16, 0.22, 8.5, x, baseY + 4.25, z, { segments: 7, collide: true })
    this.box('woodDark', 2.4, 0.14, 0.14, x, baseY + 7.9, z, { collide: false })
    this.box('woodDark', 1.4, 0.12, 0.12, x, baseY + 7.2, z, { collide: false })
    for (const off of [-1.1, 1.1]) this.box('white', 0.1, 0.4, 0.1, x + off, baseY + 8.15, z, { collide: false })
  }

  addLoot(ctx, lx, lz, y, kind, weapon) {
    const p = this.local(ctx, lx, lz)
    this.world.addLootPoint(p.x, y, p.z, kind, weapon)
  }

  flush(scene) {
    const meshes = []
    for (const [key, geos] of this.batches) {
      const merged = mergeGeometries(geos.map((g) => (g.index ? g.toNonIndexed() : g)), false)
      if (!merged) continue
      merged.computeBoundingSphere()
      const mesh = new THREE.Mesh(merged, this.getMaterial(key))
      mesh.castShadow = key !== 'glass' && key !== 'glassDark'
      mesh.receiveShadow = true
      mesh.name = `batch-${key}`
      scene.add(mesh)
      meshes.push(mesh)
      geos.forEach((g) => g.dispose())
    }
    this.batches.clear()
    return meshes
  }
}

  this.push(key, geo)
  return geo
}

// Convert a point in a building's local space to world space.
local(ctx, lx, lz) {
  const c = Math.cos(ctx.rot)
  const s = Math.sin(ctx.rot)
  return { x: ctx.x + lx * c - lz * s, z: ctx.z + lx * s + lz * c }
}

lbox(key, ctx, w, h, d, lx, y, lz, opts = {}) {
  const p = this.local(ctx, lx, lz)
  return this.box(key, w, h, d, p.x, y, p.z, { ...opts, ry: (opts.ry || 0) + ctx.rot })
}

/**
 * Build a wall with real door and window openings.
 * Runs along local X. `openings` = [{type:'door'|'window', at:0..1, width}]
 */
wall(key, ctx, len, baseY, height, lz, openings = [], opts = {}) {
  const thickness = opts.thickness || 0.28
  const bands = [
    [0.03, Math.min(0.95, height * 0.32)],
    [Math.min(0.95, height * 0.32), Math.min(2.15, height * 0.72)],
    [Math.min(2.15, height * 0.72), height]
  ]
  const lifts = openings.map((o) => {
    const center = (o.at - 0.5) * len
    return { ...o, lo: center - o.width / 2, hi: center + o.width / 2, top: o.type === 'door' ? Math.min(2.2, height) : Math.min(2.18, height) }
  })
  for (const [lo, hi] of bands) {
    if (hi - lo < 0.03) continue
    let intervals = [[-len / 2, len / 2]]
    for (const op of lifts) {
      if (op.top <= lo || op.top < lo + 0.02) continue
      if (op.type === 'door') {
        // Door gap extends from floor to its top.
        intervals = subtract(intervals, op.lo, op.hi)
      } else if (lo >= 0.8 && hi <= 2.25) {
        intervals = subtract(intervals, op.lo, op.hi)
      }
    }
    for (const [a, b] of intervals) {
      const width = b - a
      if (width < 0.06) continue
      this.lbox(key, ctx, width, hi - lo, thickness, (a + b) / 2, baseY + (lo + hi) / 2, lz, { collide: true })
    }
  }
  // Frames, sills and glass.
  for (const op of lifts) {
    const midY = op.type === 'door' ? baseY + op.top / 2 : baseY + 1.55
    this.lbox('trim', ctx, op.width + 0.24, 0.1, thickness + 0.12, (op.lo + op.hi) / 2, baseY + op.top + 0.03, lz, { collide: false })
    this.lbox('trim', ctx, 0.12, op.top, thickness + 0.12, op.lo - 0.03, baseY + op.top / 2, lz, { collide: false })
    this.lbox('trim', ctx, 0.12, op.top, thickness + 0.12, op.hi + 0.03, baseY + op.top / 2, lz, { collide: false })
    if (op.type === 'door') {
      this.lbox('trim', ctx, op.width, 0.12, thickness + 0.14, (op.lo + op.hi) / 2, baseY + op.top, lz, { collide: false })
      // A door hanging open against the inside wall.
      this.lbox('woodDark', ctx, op.width * 0.96, op.top - 0.1, 0.08, op.lo + 0.08, baseY + op.top / 2, lz + (lz > 0 ? -0.75 : 0.75), { ry: op.lo + 0.4, collide: false })
      this.lbox('concreteDark', ctx, op.width, 0.16, thickness + 0.4, (op.lo + op.hi) / 2, baseY + 0.05, lz, { collide: false })
    } else {
      const glassY = baseY + 1.55
      this.lbox('glass', ctx, op.width - 0.05, 1.1, 0.05, (op.lo + op.hi) / 2, glassY, lz, { collide: false })
      this.lbox('trim', ctx, 0.06, 1.12, 0.09, (op.lo + op.hi) / 2, glassY, lz, { collide: false })
      this.lbox('trim', ctx, op.width, 0.06, 0.09, (op.lo + op.hi) / 2, baseY + 2.1, lz, { collide: false })
      this.lbox('trimPale', ctx, op.width + 0.2, 0.09, 0.42, (op.lo + op.hi) / 2, baseY + 0.92, lz + Math.sign(lz) * 0.08, { collide: false })
    }
  }
  // Wall cap
  this.lbox('trimPale', ctx, len + 0.06, 0.09, thickness + 0.1, 0, baseY + height + 0.02, lz, { collide: false })
}

gableRoof(ctx, w, d, eaveY, angle, key = 'roof', gableKey = 'gablePlaster') {
  const halfD = d / 2
  const rise = Math.tan(angle) * halfD
  const slopeLen = halfD / Math.cos(angle) + 0.55
  const roofW = w + 1.2
  // Front and back slabs
  this.lbox(key, ctx, roofW, 0.18, slopeLen, 0, eaveY + rise / 2 + 0.08, halfD / 2, { rx: angle, collide: false })
  this.lbox(key, ctx, roofW, 0.18, slopeLen, 0, eaveY + rise / 2 + 0.08, -halfD / 2, { rx: -angle, collide: false })
  // Ridge
  this.lbox('trim', ctx, roofW + 0.1, 0.22, 0.3, 0, eaveY + rise + 0.13, 0, { collide: false })
  // Gable fills
  for (const side of [-1, 1]) {
    const lx = (side * w) / 2
    const a = this.local(ctx, lx, -halfD)
    const b = this.local(ctx, lx, halfD)
    const c = this.local(ctx, lx, 0)
    this.tri(gableKey, [a.x, eaveY, a.z], [b.x, eaveY, b.z], [c.x, eaveY + rise, c.z])
    this.tri(gableKey, [b.x, eaveY, b.z], [a.x, eaveY, a.z], [c.x, eaveY + rise, c.z])
  }
  // Eave fascia
  this.lbox('trim', ctx, roofW, 0.16, 0.14, 0, eaveY + 0.04, halfD + 0.5, { collide: false })
  this.lbox('trim', ctx, roofW, 0.16, 0.14, 0, eaveY + 0.04, -halfD - 0.5, { collide: false })
}

flatRoof(ctx, w, d, y, key = 'roof') {
  this.lbox(key, ctx, w + 0.5, 0.24, d + 0.5, 0, y + 0.12, 0, { collide: true })
  // Parapet
  this.lbox('concreteDark', ctx, w + 0.5, 0.55, 0.22, 0, y + 0.45, d / 2 + 0.14, { collide: true })
  this.lbox('concreteDark', ctx, w + 0.5, 0.55, 0.22, 0, y + 0.45, -d / 2 - 0.14, { collide: true })
  this.lbox('concreteDark', ctx, 0.22, 0.55, d + 0.5, w / 2 + 0.14, y + 0.45, 0, { collide: true })
  this.lbox('concreteDark', ctx, 0.22, 0.55, d + 0.5, -w / 2 - 0.14, y + 0.45, 0, { collide: true })
  this.lbox('trimPale', ctx, w + 0.6, 0.06, 0.26, 0, y + 0.74, d / 2 + 0.14, { collide: false })
}

house(o) {
  const ctx = { x: o.x, z: o.z, rot: o.rot || 0, baseY: this.world.getHeight(o.x, o.z) }
  const w = o.w || 12
  const d = o.d || 9
  const floors = o.floors || 1
  const wallKey = o.wall || 'plaster'
  const floorY = ctx.baseY + 0.16
  const h1 = o.h1 || 3.05
  // Foundation + ground slab
  this.lbox('foundation', ctx, w + 0.7, 1.1, d + 0.7, 0, ctx.baseY - 0.5, 0, { collide: true })
  this.lbox('concreteDark', ctx, w + 0.35, 0.2, d + 0.35, 0, ctx.baseY - 0.02, 0, { collide: true })
  this.lbox(o.floorKey || 'woodPale', ctx, w - 0.28, 0.14, d - 0.28, 0, floorY - 0.07, 0, { collide: true, platform: true })
  // Ground floor walls
  const frontOpenings = [
    { type: 'door', at: o.doorAt ?? 0.5, width: 1.35 },
    { type: 'window', at: 0.16, width: 1.45 },
    { type: 'window', at: 0.84, width: 1.45 }
  ]
  const sideOpenings = [
    { type: 'window', at: 0.28, width: 1.3 },
    { type: 'window', at: 0.72, width: 1.3 }
  ]
  const backOpenings = [
    { type: 'door', at: 0.32, width: 1.2 },
    { type: 'window', at: 0.72, width: 1.4 }
  ]
  this.wall(wallKey, ctx, w, floorY, h1, d / 2, frontOpenings)
  this.wall(wallKey, ctx, w, floorY, h1, -d / 2, backOpenings)
  this.wallRotated(wallKey, ctx, d, floorY, h1, w / 2, sideOpenings)
  this.wallRotated(wallKey, ctx, d, floorY, h1, -w / 2, sideOpenings)
  this.lbox('trim', ctx, 0.3, h1, 0.34, w / 2 - 0.1, floorY + h1 / 2, d / 2 - 0.1, { collide: false })
  this.lbox('trim', ctx, 0.3, h1, 0.34, -w / 2 + 0.1, floorY + h1 / 2, d / 2 - 0.1, { collide: false })
  this.lbox('trim', ctx, 0.3, h1, 0.34, w / 2 - 0.1, floorY + h1 / 2, -d / 2 + 0.1, { collide: false })
  this.lbox('trim', ctx, 0.3, h1, 0.34, -w / 2 + 0.1, floorY + h1 / 2, -d / 2 + 0.1, { collide: false })
  // Interior partition
  const partY = floorY + h1 / 2
  this.lbox(wallKey, ctx, 0.22, h1, d - 1.6, -w * 0.18, partY, 0.1, { collide: true })
  this.lbox('trim', ctx, 0.28, 2.1, 1.2, -w * 0.18, floorY + 1.05, d * 0.18, { collide: false })
  this.lbox(wallKey, ctx, 0.22, 0.95, 1.2, -w * 0.18, floorY + 2.6, d * 0.18, { collide: false })
  // Ceiling / upper floor
  const upperY = floorY + h1
  if (floors > 1) {
    const holeX0 = -w / 2 + 0.55
    const holeX1 = holeX0 + 1.85
    const holeZ0 = -d / 2 + 0.55
    const holeZ1 = holeZ0 + 4.15
    const slabY = upperY + 0.09
    const addSlab = (x0, x1, z0, z1) => {
      const sw = x1 - x0
      const sd = z1 - z0
      if (sw < 0.1 || sd < 0.1) return
      this.lbox(o.floorKey || 'woodPale', ctx, sw, 0.18, sd, (x0 + x1) / 2, upperY, (z0 + z1) / 2, { collide: true, platform: true })
    }
    addSlab(-w / 2, w / 2, -d / 2, holeZ0)
    addSlab(-w / 2, holeX0, holeZ0, holeZ1)
    addSlab(holeX1, w / 2, holeZ0, holeZ1)
    addSlab(-w / 2, w / 2, holeZ1, d / 2)
    // Stairs up through the hole
    const steps = 10
    const stepH = (h1 - 0.05) / steps
    const stepD = 4.0 / steps
    for (let i = 0; i < steps; i++) {
      const sy = floorY + stepH * (i + 1)
      const sz = holeZ1 - stepD * (i + 0.5)
      this.lbox('woodDark', ctx, 1.75, 0.13, stepD + 0.04, (holeX0 + holeX1) / 2, sy - 0.065, sz, { collide: false, platform: true })
      this.lbox('trim', ctx, 0.12, stepH, stepD + 0.04, holeX0 + 0.08, sy - stepH / 2, sz, { collide: false })
    }
    // Railing around the opening
    const railY = upperY + 0.95
    this.lbox('woodDark', ctx, 0.1, 0.95, 0.1, holeX1, railY - 0.45, holeZ0, { collide: false })
    this.lbox('woodDark', ctx, 0.1, 0.95, 0.1, holeX1, railY - 0.45, holeZ1, { collide: false })
    this.lbox('woodDark', ctx, 0.09, 0.09, holeZ1 - holeZ0, holeX1, railY, (holeZ0 + holeZ1) / 2, { collide: false })
    this.lbox('woodDark', ctx, 0.1, 0.95, 0.1, holeX0, railY - 0.45, holeZ1, { collide: false })
    // Upper floor walls
    const h2 = o.h2 || 2.75
    const upY = upperY + 0.18
    this.wall(wallKey, ctx, w, upY, h2, d / 2, [{ type: 'window', at: 0.2, width: 1.4 }, { type: 'window', at: 0.62, width: 1.4 }])
    this.wall(wallKey, ctx, w, upY, h2, -d / 2, [{ type: 'window', at: 0.3, width: 1.5 }, { type: 'window', at: 0.76, width: 1.2 }])
    // Side walls are built as rotated runs.
    this.wallRotated(wallKey, ctx, d, upY, h2, w / 2, [{ type: 'window', at: 0.3, width: 1.3 }, { type: 'window', at: 0.7, width: 1.3 }])
    this.wallRotated(wallKey, ctx, d, upY, h2, -w / 2, [{ type: 'window', at: 0.3, width: 1.3 }, { type: 'window', at: 0.7, width: 1.3 }])
    this.lbox('trim', ctx, w, 0.18, d, 0, upperY + 0.02, 0, { collide: false })
    const roofY = upY + h2
    if (o.roof === 'flat') this.flatRoof(ctx, w, d, roofY)
    else this.gableRoof(ctx, w, d, roofY + 0.2, 0.4, o.roofKey || 'roof', o.gableKey || 'gablePlaster')
  } else {
    this.lbox('woodPale', ctx, w - 0.3, 0.16, d - 0.3, 0, upperY + 0.02, 0, { collide: true, platform: true })
    const roofY = upperY + 0.18
    if (o.roof === 'flat') this.flatRoof(ctx, w, d, roofY)
    else this.gableRoof(ctx, w, d, roofY + 0.2, 0.42, o.roofKey || 'roof', o.gableKey || 'gablePlaster')
  }
  // Porch
  if (o.porch !== false) {
    const pz = d / 2 + 1.35
    this.lbox('concreteDark', ctx, 3.6, 0.22, 2.7, 0, floorY - 0.12, pz, { collide: true, platform: true })
    for (const sx of [-1.55, 1.55]) {
      this.lbox('woodDark', ctx, 0.16, 2.5, 0.16, sx, floorY + 1.2, pz + 1.1, { collide: true })
    }
    this.lbox('roof', ctx, 4.1, 0.13, 3.0, 0, floorY + 2.55, pz, { collide: false })
    this.lbox('trim', ctx, 4.1, 0.28, 0.14, 0, floorY + 2.42, pz + 1.5, { collide: false })
    this.lbox('woodDark', ctx, 0.9, 0.12, 0.5, 0.1, floorY + 0.4, pz - 0.8, { collide: false })
  }
  // Chimney
  if (o.chimney !== false) {
    this.lbox('concreteDark', ctx, 1.05, floors > 1 ? 7.2 : 4.6, 1.05, w * 0.31, ctx.baseY + 2.7, -d * 0.28, { collide: true })
    this.lbox('concreteDark', ctx, 1.2, 0.22, 1.2, w * 0.31, ctx.baseY + (floors > 1 ? 6.3 : 3.8), -d * 0.28, { collide: false })
    const pipe = this.local(ctx, w * 0.31, -d * 0.28)
    this.box('darkMetal', 0.16, 1.1, 0.16, pipe.x, ctx.baseY + (floors > 1 ? 7.0 : 4.5), pipe.z, { collide: false })
  }
  // Porch light + step
  this.lbox('trimPale', ctx, 1.9, 0.2, 0.6, 0, ctx.baseY + 0.12, d / 2 + 0.55, { collide: false })
  return ctx
}

localArr(ctx, lx, lz) {
  const p = this.local(ctx, lx, lz)
  return [p.x, 0, p.z]
}

// Wall along local Z (rotated 90 degrees).
wallRotated(key, ctx, len, baseY, height, lx, openings = []) {
  const runCtx = { ...ctx, x: this.local(ctx, lx, 0).x, z: this.local(ctx, lx, 0).z, rot: ctx.rot + Math.PI / 2 }
  // Pull the wall run back into its opening plane.
  const p = this.local(ctx, lx, 0)
  runCtx.x = p.x
  runCtx.z = p.z
  this.wall(key, runCtx, len, baseY, height, 0, openings)
}

warehouse(o) {
  const ctx = { x: o.x, z: o.z, rot: o.rot || 0, baseY: this.world.getHeight(o.x, o.z) }
  const w = o.w || 20
  const d = o.d || 11
  const h = o.h || 5.4
  const floorY = ctx.baseY + 0.14
  const wallKey = o.wall || 'metal'
  this.lbox('foundation', ctx, w + 0.8, 1.2, d + 0.8, 0, ctx.baseY - 0.52, 0, { collide: true })
  this.lbox('concrete', ctx, w + 0.3, 0.2, d + 0.3, 0, ctx.baseY - 0.02, 0, { collide: true })
  this.lbox('concreteDark', ctx, w - 0.3, 0.14, d - 0.3, 0, floorY - 0.07, 0, { collide: true, platform: true })
  // Front rolling door opening (5m)
  this.wall(wallKey, ctx, w, floorY, h, d / 2, [{ type: 'door', at: 0.5, width: 5.0 }])
  this.wall(wallKey, ctx, w, floorY, h, -d / 2, [{ type: 'door', at: 0.5, width: 3.2 }])
  this.wallRotated(wallKey, ctx, d, floorY, h, w / 2, [{ type: 'window', at: 0.3, width: 2.4 }, { type: 'window', at: 0.7, width: 2.4 }])
  this.wallRotated(wallKey, ctx, d, floorY, h, -w / 2, [{ type: 'window', at: 0.3, width: 2.4 }, { type: 'window', at: 0.7, width: 2.4 }])
  // Yellow safety stripe at door
  this.lbox('orange', ctx, 5.2, 0.18, 0.2, 0, floorY + 0.2, d / 2 + 0.2, { collide: false })
  // Interior office
  this.lbox('plaster', ctx, 4.4, 3.0, 3.2, -w / 2 + 2.5, floorY + 1.5, -d / 2 + 2.0, { collide: true })
  this.lbox('glass', ctx, 1.0, 1.0, 0.08, -w / 2 + 2.5, floorY + 1.8, -d / 2 + 3.62, { collide: false })
  this.lbox('darkMetal', ctx, 0.95, 2.15, 0.1, -w / 2 + 4.4, floorY + 1.07, -d / 2 + 3.6, { collide: false })
  // Roof + skylights
  this.flatRoof(ctx, w, d, floorY + h)
  for (const sx of [-w * 0.28, 0, w * 0.28]) {
    this.lbox('glassDark', ctx, 2.4, 0.1, 1.5, sx, floorY + h + 0.32, 0, { collide: false })
    this.lbox('trim', ctx, 2.6, 0.16, 1.7, sx, floorY + h + 0.24, 0, { collide: false })
  }
  // Roof vents
  this.lbox('metal', ctx, 1.1, 0.7, 1.1, w * 0.32, floorY + h + 0.7, d * 0.25, { collide: false })
  // Loading dock
  this.lbox('concreteDark', ctx, w * 0.7, 0.55, 3.2, 0, ctx.baseY - 0.12, d / 2 + 1.9, { collide: true, platform: true })
  for (let i = 0; i < 5; i++) {
    this.lbox('concreteDark', ctx, 2.4, 0.13, 0.5, 0, ctx.baseY - 0.35 + i * 0.11, d / 2 + 4.1 - i * 0.42, { collide: false, platform: true })
  }
  // Interior crates
  for (const [lx, lz, s] of [[-6, 2, 1.2], [-4.6, 2.6, 0.9], [5.5, -3, 1.35], [6.8, -2.4, 1.0], [3.1, 2.2, 0.8]]) {
    this.crate(ctx, lx, lz, floorY, s)
  }
  this.addLoot(ctx, 6, 1.6, floorY, 'weapon')
  this.addLoot(ctx, -5.5, 1.8, floorY, 'ammo')
  this.addLoot(ctx, 2.4, -3.0, floorY, 'armor')
  return ctx
}

cabin(o) {
  const ctx = this.house({
    ...o,
    w: o.w || 8,
    d: o.d || 7,
    floors: 1,
    wall: o.wall || 'wood',
    floorKey: 'woodPale',
    roof: o.roof || 'gable',
    gableKey: 'gableWood',
    doorAt: 0.5,
    chimney: o.chimney !== false
  })
  return ctx
}

shop(o) {
  const ctx = this.house({
    ...o,
    w: o.w || 11,
    d: o.d || 9,
    floors: 2,
    wall: 'plasterWarm',
    roof: 'flat',
    porch: true,
    doorAt: 0.5,
    chimney: false
  })
  // Awning + sign
  const p = this.local(ctx, 0, (o.d || 9) / 2 + 1.6)
  this.box('orange', 6.2, 0.28, 2.0, p.x, ctx.baseY + 3.0, p.z, { ry: ctx.rot, collide: false })
  this.box('white', 3.6, 0.52, 0.12, p.x, ctx.baseY + 3.5, p.z + 0.2, { ry: ctx.rot, collide: false })

/* ============================================================
   HUD
   ============================================================ */
#hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; opacity: 1; transition: opacity 0.4s; }
#hud.hidden { opacity: 0; visibility: hidden; }

.hud-top { position: absolute; top: calc(10px + var(--safe-top)); left: 0; right: 0; display: flex; justify-content: center; }
#compass { position: absolute; top: 0; width: min(600px, 52vw); height: 40px; opacity: 0.9; }
#zoneBanner {
  position: absolute; top: 46px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px;
  padding: 5px 14px 4px;
  background: rgba(6, 9, 10, 0.55); border: 1px solid var(--line-soft); border-radius: 2px;
  backdrop-filter: blur(6px);
  font-family: 'Rajdhani', sans-serif; font-size: 11px; font-weight: 700; letter-spacing: 0.16em;
}
.zone-kicker { color: #7f8b8b; font-size: 9px; letter-spacing: 0.22em; }
#zoneTimer { font-size: 15px; font-weight: 700; color: #eae6dc; font-variant-numeric: tabular-nums; }
.zone-state { color: var(--orange); font-size: 9px; letter-spacing: 0.16em; }
#zoneBanner.danger .zone-state, #zoneBanner.closing .zone-state { color: #ff5c4d; }
#zoneBanner.closing { border-color: rgba(255, 92, 77, 0.4); }

.match-counts {
  position: absolute; top: 4px; right: 18px;
  display: flex; gap: 18px; align-items: flex-start;
  background: linear-gradient(180deg, rgba(6, 9, 10, 0.74), rgba(6, 9, 10, 0.42));
  border: 1px solid var(--line-soft); border-radius: 2px;
  padding: 8px 14px 7px;
  backdrop-filter: blur(8px);
}
.count { display: flex; flex-direction: column; align-items: flex-end; }
.count span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 27px; line-height: 0.9; color: #f2efe6; font-variant-numeric: tabular-nums; }
.count small { font-size: 8px; font-weight: 700; letter-spacing: 0.24em; color: #8b9492; margin-top: 4px; }
.count.divider { border-left: 1px solid var(--line-soft); padding-left: 18px; }
.count.divider span { color: var(--orange); }

#killfeed {
  position: absolute; top: 74px; right: 18px;
  display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
  width: 330px;
}
.feed-item {
  display: flex; align-items: center; gap: 8px;
  padding: 5px 9px;
  background: rgba(6, 9, 10, 0.65);
  border-right: 2px solid var(--orange);
  font-family: 'Rajdhani', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0.04em;
  color: #cfd3cc;
  animation: feedIn 0.25s ease both;
  backdrop-filter: blur(5px);
}
.feed-item.fade { opacity: 0; transition: opacity 0.6s; }
.feed-item b { color: #f2efe6; font-weight: 700; }
.feed-item .weapon { color: var(--orange); font-size: 10px; letter-spacing: 0.1em; }
.feed-item .hs { color: #ffd257; font-size: 9px; letter-spacing: 0.16em; }
.feed-item.player { border-right-color: var(--orange); background: rgba(255, 122, 24, 0.12); }
.feed-item.player b:last-of-type { color: #ffb066; }

#zoneWarning {
  position: absolute; top: 96px; left: 50%; transform: translateX(-50%);
  display: none; flex-direction: column; align-items: center; gap: 2px;
  padding: 8px 20px;
  border: 1px solid rgba(255, 70, 55, 0.55);
  background: rgba(70, 8, 4, 0.55);
  box-shadow: 0 0 40px rgba(255, 40, 20, 0.25);
  animation: dangerPulse 1.4s ease-in-out infinite;
}
#zoneWarning.show { display: flex; }
#zoneWarning strong { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #ff6656; }
#zoneWarning span { font-size: 9px; font-weight: 700; letter-spacing: 0.2em; color: #ffb5aa; }

/* crosshair */
#crosshair {
  position: absolute; left: 50%; top: 50%; width: 2px; height: 2px;
  --gap: calc(var(--spread) + 3px);
  opacity: 0.95;
  transition: opacity 0.15s;
}
#crosshair.hide { opacity: 0; }
.ch-dot { position: absolute; left: -1px; top: -1px; width: 3px; height: 3px; background: #f4f1e8; border-radius: 50%; box-shadow: 0 0 4px rgba(0, 0, 0, 0.9); }
.ch-line { position: absolute; background: #f4f1e8; box-shadow: 0 0 3px rgba(0, 0, 0, 0.9), 0 0 1px rgba(0, 0, 0, 1); opacity: 0.9; transition: transform 0.08s ease-out; }
.ch-line.t { width: 2px; height: 9px; left: -1px; top: calc(-1 * var(--gap) - 9px); }
.ch-line.b { width: 2px; height: 9px; left: -1px; top: var(--gap); }
.ch-line.l { width: 9px; height: 2px; top: -1px; left: calc(-1 * var(--gap) - 9px); }
.ch-line.r { width: 9px; height: 2px; top: -1px; left: var(--gap); }

#hitmarker { position: absolute; left: 50%; top: 50%; width: 0; height: 0; opacity: 0; }
#hitmarker span { position: absolute; width: 2px; height: 9px; background: #fff; box-shadow: 0 0 4px rgba(0, 0, 0, 0.8); left: -1px; top: -4px; }
#hitmarker span:nth-child(1) { transform: rotate(45deg) translate(0, -13px); }
#hitmarker span:nth-child(2) { transform: rotate(45deg) translate(0, 13px); }
#hitmarker span:nth-child(3) { transform: rotate(-45deg) translate(0, -13px); }
#hitmarker span:nth-child(4) { transform: rotate(-45deg) translate(0, 13px); }
#hitmarker.show { animation: hitPop 0.28s ease-out; }
#hitmarker.headshot span { background: #ffd257; }
#hitmarker.kill span { background: #ff5a45; }

#damageDir {
  position: absolute; left: 50%; top: 50%; width: 170px; height: 170px; margin: -85px 0 0 -85px;
  border-radius: 50%; opacity: 0; pointer-events: none;
  background: conic-gradient(from 0deg, transparent 0deg, rgba(255, 45, 30, 0.55) 16deg, transparent 34deg);
  filter: blur(2px);
  transition: opacity 0.1s;
}
#damageVignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 38%, rgba(160, 12, 6, 0.45) 82%, rgba(120, 5, 2, 0.72) 100%);
  transition: opacity 0.25s;
}
#damageVignette.zone {
  opacity: 0.55;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(20, 80, 160, 0.3) 78%, rgba(10, 50, 120, 0.6) 100%);
  animation: zoneVignette 2s ease-in-out infinite;
}

/* prompts */
#interactPrompt, #harvestPrompt {
  position: absolute; left: 50%; top: 61%; transform: translateX(-50%);
  display: none; align-items: center; gap: 9px;
  padding: 7px 14px 7px 9px;
  background: rgba(7, 10, 11, 0.78);
  border: 1px solid rgba(255, 122, 24, 0.4);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 12px; letter-spacing: 0.16em;
  backdrop-filter: blur(6px);
}
#interactPrompt.show, #harvestPrompt.show { display: flex; }
#interactPrompt kbd, #harvestPrompt kbd { border-color: var(--orange); color: var(--orange); background: rgba(255, 122, 24, 0.1); }
#harvestPrompt { top: 66%; }

#healProgress {
  position: absolute; left: 50%; top: 57%; transform: translateX(-50%);
  display: none; width: 220px; flex-direction: column; gap: 5px;
}
#healProgress.show { display: flex; }
.heal-label { font-size: 9px; font-weight: 700; letter-spacing: 0.22em; color: #9ee7b2; text-align: center; }
.heal-track { height: 3px; background: rgba(255, 255, 255, 0.16); overflow: hidden; }
.heal-track i { display: block; height: 100%; width: 0%; background: #7ce69a; box-shadow: 0 0 10px rgba(124, 230, 154, 0.7); }

/* build hud */
#buildHud {
  position: absolute; left: 50%; bottom: calc(118px + var(--safe)); transform: translateX(-50%);
  display: none; flex-direction: column; align-items: center; gap: 8px;
  padding: 10px 14px 11px;
  background: rgba(7, 10, 11, 0.74);
  border: 1px solid rgba(255, 122, 24, 0.28);
  backdrop-filter: blur(8px);
  min-width: 390px;
}
#buildHud.show { display: flex; }
.build-title { display: flex; align-items: baseline; gap: 12px; }
.build-title span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 15px; letter-spacing: 0.22em; color: var(--orange); }
.build-title small { font-size: 8px; font-weight: 700; letter-spacing: 0.14em; color: #75807e; }
.build-pieces { display: flex; gap: 6px; }
.piece {
  position: relative; display: flex; align-items: center; gap: 7px;
  padding: 7px 12px 7px 7px; min-width: 100px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03);
  transition: 0.15s;
}
.piece.active { border-color: var(--orange); background: rgba(255, 122, 24, 0.14); box-shadow: inset 0 0 20px rgba(255, 122, 24, 0.08); }
.piece b { width: 18px; height: 18px; display: grid; place-items: center; font-size: 10px; background: rgba(255, 255, 255, 0.1); color: #e8e4da; }
.piece.active b { background: var(--orange); color: #170d05; }
.piece span { font-size: 10px; font-weight: 700; letter-spacing: 0.16em; color: #c8cdc6; }
.piece em { margin-left: auto; font-style: normal; font-size: 10px; font-weight: 700; color: var(--orange); }
.wood-count { display: flex; align-items: center; gap: 7px; font-family: 'Rajdhani', sans-serif; }
.wood-icon { width: 13px; height: 13px; background: linear-gradient(135deg, #b8864b, #7d5426); box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.3); }
.wood-count strong { font-size: 18px; font-weight: 700; color: #f2efe6; line-height: 1; }
.wood-count small { font-size: 8px; font-weight: 700; letter-spacing: 0.2em; color: #7f8987; }

/* bottom */
.hud-bottom {
  position: absolute; left: 18px; right: 18px; bottom: calc(14px + var(--safe));
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px;
}
.vitals {
  width: 310px; padding: 11px 13px 9px;
  background: linear-gradient(180deg, rgba(7, 10, 11, 0.5), rgba(7, 10, 11, 0.78));
  border: 1px solid var(--line-soft);
  border-left: 2px solid var(--orange);
  backdrop-filter: blur(8px);
}
.vital-row { display: grid; grid-template-columns: 18px 1fr 36px; align-items: center; gap: 8px; margin-bottom: 6px; }
.vital-icon { width: 15px; height: 15px; position: relative; opacity: 0.85; }
.vital-icon.health::before { content: ''; position: absolute; inset: 3px; background: #f2efe6; clip-path: polygon(50% 100%, 0 45%, 0 18%, 25% 0, 50% 18%, 75% 0, 100% 18%, 100% 45%); }
.vital-icon.armor::before { content: ''; position: absolute; inset: 2px 3px; background: #9fc6e8; clip-path: polygon(50% 0, 100% 18%, 100% 62%, 50% 100%, 0 62%, 0 18%); }
.vital-track { height: 8px; background: rgba(255, 255, 255, 0.09); overflow: hidden; position: relative; }
.vital-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #d8d5cc, #f5f2e9); transition: width 0.25s ease; }
.armor-row .vital-track { height: 5px; }
.armor-row .vital-track i { background: linear-gradient(90deg, #5b8db8, #9fc6e8); width: 0%; }
.vital-row strong { font-family: 'Barlow Condensed', sans-serif; font-size: 19px; font-weight: 700; line-height: 1; text-align: right; color: #f0ede4; font-variant-numeric: tabular-nums; }
.armor-row strong { font-size: 14px; color: #a9c8e2; }
.vital-sub { display: flex; align-items: center; justify-content: space-between; margin-top: 3px; font-size: 9px; font-weight: 700; letter-spacing: 0.13em; color: #8b9492; }
.vital-sub span { display: flex; align-items: center; gap: 5px; }
.vital-sub b { color: #d8d4ca; font-size: 11px; }
.vital-sub kbd { font-size: 8px; padding: 2px 4px 1px; }
.chip.med { width: 10px; height: 10px; background: #d8d4ca; clip-path: polygon(35% 0, 65% 0, 65% 35%, 100% 35%, 100% 65%, 65% 65%, 65% 100%, 35% 100%, 35% 65%, 0 65%, 0 35%, 35% 35%); }
.mode-tag { color: #6d7775; }
.mode-tag.crouch { color: var(--orange); }

.weapon-panel {
  display: grid;
  grid-template-columns: auto auto;
  grid-template-areas: 'name ammo' 'slots slots';
  align-items: end; gap: 2px 16px;
  padding: 9px 14px 10px;
  min-width: 280px;
  background: linear-gradient(180deg, rgba(7, 10, 11, 0.5), rgba(7, 10, 11, 0.8));
  border: 1px solid var(--line-soft);
  backdrop-filter: blur(8px);
  position: relative;
}
.weapon-name { grid-area: name; display: flex; flex-direction: column; gap: 2px; }
.weapon-name span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 23px; letter-spacing: 0.08em; line-height: 1; color: #f2efe6; }
.weapon-name small { font-size: 8px; font-weight: 700; letter-spacing: 0.22em; color: var(--orange); }
.ammo { grid-area: ammo; display: flex; align-items: baseline; gap: 4px; font-family: 'Barlow Condensed', sans-serif; }
.ammo strong { font-size: 44px; font-weight: 700; line-height: 0.85; color: #f5f2e9; font-variant-numeric: tabular-nums; }
.ammo span { color: #5e6866; font-size: 18px; }
.ammo em { font-style: normal; font-size: 17px; font-weight: 600; color: #8d9694; }
.ammo.low strong { color: var(--orange); }
.weapon-slots { grid-area: slots; display: flex; gap: 6px; margin-top: 6px; }
.slot { flex: 1; display: flex; align-items: center; gap: 7px; padding: 4px 7px; border: 1px solid var(--line-soft); background: rgba(255, 255, 255, 0.025); font-size: 9px; font-weight: 700; letter-spacing: 0.12em; color: #89928f; min-height: 23px; }
.slot b { color: #666f6d; font-size: 9px; }
.slot.active { border-color: rgba(255, 122, 24, 0.45); background: rgba(255, 122, 24, 0.1); color: #e3ded4; }
.slot.active b { color: var(--orange); }
.slot span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.reload-hint { position: absolute; left: 14px; top: -19px; font-size: 9px; font-weight: 700; letter-spacing: 0.14em; color: #cdd2ca; opacity: 0; transition: opacity 0.2s; }
.reload-hint.show { opacity: 1; animation: blink 1.1s step-end infinite; }

.minimap-wrap { position: relative; width: 182px; height: 182px; background: #07100d; border: 1px solid rgba(255, 255, 255, 0.16); box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4); }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: -1px; border: 1px solid rgba(255, 122, 24, 0.35); pointer-events: none; }
.minimap-ring::before, .minimap-ring::after { content: ''; position: absolute; width: 9px; height: 9px; border: 1px solid var(--orange); }
.minimap-ring::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.minimap-ring::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }
.minimap-label { position: absolute; bottom: 3px; right: 5px; font-size: 8px; font-weight: 700; letter-spacing: 0.16em; color: rgba(255, 255, 255, 0.42); }

#toast {
  position: absolute; left: 50%; top: 125px; transform: translate(-50%, -8px);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 18px; letter-spacing: 0.24em;
  color: #f5f2e9; text-align: center; opacity: 0; transition: opacity 0.3s, transform 0.3s;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.8);
  pointer-events: none;
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast small { font-family: 'Rajdhani', sans-serif; font-size: 10px; letter-spacing: 0.2em; color: var(--orange); font-weight: 700; }

#damageNumbers { position: absolute; inset: 0; overflow: hidden; }
.dmg-num { position: absolute; transform: translate(-50%, -50%); font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 19px; color: #fff; text-shadow: 0 2px 6px rgba(0, 0, 0, 0.9); animation: dmgFloat 0.75s ease-out forwards; white-space: nowrap; }
.dmg-num.head { color: #ffd257; font-size: 24px; }
.dmg-num.kill { color: #ff6a55; font-size: 22px; }

/* ============================================================
   TOUCH
   ============================================================ */
#touch { position: absolute; inset: 0; z-index: 22; display: none; pointer-events: none; }
body.touch #touch { display: block; }
body.touch #touch.hidden { display: none; }
.touch-zone { position: absolute; pointer-events: auto; }
/* ============================================================
   PAUSE / END
   ============================================================ */
.screen.compact {
  display: flex; align-items: center; justify-content: center;
  background: rgba(4, 7, 8, 0.66);
  backdrop-filter: blur(10px);
  padding: 24px;
}
.screen.compact.hidden { display: none; }
.pause-card, .end-card {
  width: min(560px, 100%);
  background: linear-gradient(165deg, rgba(15, 20, 21, 0.97), rgba(6, 9, 10, 0.97));
  border: 1px solid var(--line);
  padding: 32px 34px 28px;
  position: relative;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}
.pause-card::before, .end-card::before { content: ''; position: absolute; top: 0; left: 34px; width: 90px; height: 2px; background: var(--orange); }
.pause-card h2, .end-card h2 { margin: 0 0 8px; font-family: 'Barlow Condensed', sans-serif; font-weight: 800; font-size: 52px; line-height: 0.95; letter-spacing: 0.03em; text-transform: uppercase; }
.pause-card p, .end-card p { margin: 0 0 22px; color: #9aa3a1; font-size: 13.5px; line-height: 1.5; font-weight: 500; }
.pause-actions, .end-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 22px; }
.btn-ghost {
  padding: 14px 24px; background: transparent; color: #d6d9d2; border: 1px solid var(--line);
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 12px; letter-spacing: 0.18em; text-transform: uppercase;
  cursor: pointer; transition: 0.16s;
}
.btn-ghost:hover { border-color: var(--orange); color: #fff; background: rgba(255, 122, 24, 0.08); }
.pause-keys { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px 14px; border-top: 1px solid var(--line-soft); padding-top: 16px; font-size: 9px; font-weight: 700; letter-spacing: 0.1em; color: #7f8987; text-transform: uppercase; }
.pause-keys span { display: flex; align-items: center; gap: 6px; }

.end-card { width: min(620px, 100%); }
.end-card h2 { font-size: 68px; }
#endTitle.win { color: var(--orange); text-shadow: 0 0 60px rgba(255, 122, 24, 0.3); }
.placement { display: flex; align-items: baseline; gap: 9px; margin: 4px 0 20px; }
.placement small { font-size: 9px; font-weight: 700; letter-spacing: 0.24em; color: #7d8785; }
.placement strong { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 40px; line-height: 1; color: #f2efe6; }
.placement span { font-size: 11px; font-weight: 700; letter-spacing: 0.16em; color: #6d7775; }
.end-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line-soft); border: 1px solid var(--line-soft); margin-bottom: 24px; }
.end-stats div { background: rgba(8, 11, 12, 0.6); padding: 12px 14px; }
.end-stats span { display: block; font-size: 8.5px; font-weight: 700; letter-spacing: 0.2em; color: #7d8785; margin-bottom: 3px; }
.end-stats strong { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 30px; line-height: 1; color: #f1eee5; }
.end-note { font-size: 10px; font-weight: 600; letter-spacing: 0.16em; color: #626c6a; text-transform: uppercase; }

/* rotate hint */
#rotateHint {
  position: absolute; inset: 0; z-index: 90; display: none;
  flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  background: #080b0c; color: var(--ink); text-align: center;
}
#rotateHint span { font-family: 'Barlow Condensed', sans-serif; font-weight: 700; font-size: 24px; letter-spacing: 0.24em; color: var(--orange); }
#rotateHint small { font-size: 11px; letter-spacing: 0.14em; color: #7f8987; text-transform: uppercase; }
.noscript { position: fixed; inset: 0; display: grid; place-items: center; background: #080b0c; z-index: 100; }

/* ============================================================
   ANIMATIONS
   ============================================================ */
@keyframes pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(255, 122, 24, 0.5); } 50% { box-shadow: 0 0 0 6px rgba(255, 122, 24, 0); } }
@keyframes scan { 0% { top: -40%; } 100% { top: 110%; } }
@keyframes ping { 0% { transform: scale(0.6); opacity: 1; } 100% { transform: scale(1.8); opacity: 0; } }

@keyframes ping { 0% { transform: scale(0.6); opacity: 1; } 100% { transform: scale(1.8); opacity: 0; } }
@keyframes feedIn { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }
@keyframes hitPop { 0% { opacity: 1; transform: scale(0.55); } 55% { opacity: 1; transform: scale(1.1); } 100% { opacity: 0; transform: scale(1); } }
@keyframes dangerPulse { 0%, 100% { box-shadow: 0 0 30px rgba(255, 40, 20, 0.15); } 50% { box-shadow: 0 0 55px rgba(255, 40, 20, 0.4); } }
@keyframes zoneVignette { 0%, 100% { opacity: 0.4; } 50% { opacity: 0.65; } }
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@keyframes dmgFloat { 0% { opacity: 0; transform: translate(-50%, -38%) scale(0.8); } 15% { opacity: 1; transform: translate(-50%, -50%) scale(1.05); } 100% { opacity: 0; transform: translate(-50%, -150%) scale(1); } }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1180px) {
  .menu-main { grid-template-columns: minmax(0, 1fr) 330px; gap: 32px; }
  .menu-panel { padding: 14px; }
  .brief-map { margin: 11px 0 10px; }
  .title { font-size: clamp(72px, 12vw, 150px); }
  .feature-strip { margin-top: 24px; }
}

@media (max-width: 900px) {
  #menu { padding: calc(16px + var(--safe-top)) 18px calc(14px + var(--safe)); }
  .menu-frame { gap: 8px; }
  .menu-main { grid-template-columns: 1fr; align-items: center; gap: 16px; overflow-y: auto; scrollbar-width: none; }
  .menu-main::-webkit-scrollbar { display: none; }
  .menu-hero { padding-left: 0; }
  .menu-panel { display: none; }
  .title { font-size: clamp(64px, 16vw, 120px); margin-bottom: 12px; }
  .tagline { font-size: 17px; }
  .lede { font-size: 13px; margin-bottom: 20px; max-width: 480px; }
  .feature-strip { grid-template-columns: 1fr; background: transparent; border-bottom: 0; gap: 0; margin-top: 18px; }
  .feature { display: none; }
  .feature:first-child { display: block; padding-left: 0; background: transparent; }
  .menu-hint { display: none; }
  .menu-foot { display: none; }
  .menu-top .menu-meta { font-size: 9px; letter-spacing: 0.12em; }
  .brand-name { font-size: 12px; letter-spacing: 0.18em; }
  .btn-primary { min-width: 250px; }
  #compass { width: 78vw; }
  .match-counts { right: 10px; padding: 6px 10px; }
  .count span { font-size: 22px; }
  #killfeed { right: 10px; width: 250px; }
  .hud-bottom { left: 10px; right: 10px; bottom: calc(8px + var(--safe)); gap: 8px; }
  .vitals { width: 228px; padding: 8px 10px; }
  .vital-row { grid-template-columns: 16px 1fr 30px; margin-bottom: 4px; }
  .vital-row strong { font-size: 16px; }
  .vital-sub { font-size: 8px; }
  .weapon-panel { min-width: 0; width: 212px; padding: 7px 10px 8px; }
  .weapon-name span { font-size: 18px; }
  .ammo strong { font-size: 32px; }
  .minimap-wrap { width: 132px; height: 132px; }
  #buildHud { bottom: calc(90px + var(--safe)); min-width: 0; padding: 7px 9px; }
  .build-title small { display: none; }
  .piece { min-width: 70px; padding: 5px 7px; }
  #zoneWarning { top: 88px; }
}

@media (max-height: 700px) {
  .feature-strip { margin-top: 16px; }
  .title { font-size: clamp(58px, 11vw, 120px); }
  .lede { margin-bottom: 16px; }
  .menu-panel .brief-map { max-height: 210px; }
  .setting { padding: 2px 0; }
}

@media (orientation: portrait) and (max-width: 620px) {
  #rotateHint { display: flex; }
}

@media (hover: none) and (pointer: coarse) {
  #crosshair { --spread: 9px; }
  .reload-hint { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

