import test from 'node:test'
import assert from 'node:assert/strict'
import {
  MATCH,
  WEAPONS,
  WEAPON_IDS,
  LOOT_WEIGHTS,
  ZONE_PHASES,
  ZONE_START_RADIUS,
  BUILD_COSTS,
  BUILD_PIECES,
  BOT_NAMES,
  SITES,
  LAKES,
  RARITY
} from '../src/config.js'

test('match is a 30-player solo with 29 bots', () => {
  assert.equal(MATCH.botCount, 29)
  assert.equal(MATCH.totalPlayers, 30)
  assert.equal(MATCH.botCount + 1, MATCH.totalPlayers)
  assert.ok(MATCH.matchTimeLimit > 0)
  assert.ok(MATCH.spawnWood >= BUILD_COSTS.wall)
})

test('weapon table is internally consistent', () => {
  assert.equal(WEAPON_IDS.length, 5)
  for (const id of WEAPON_IDS) {
    const def = WEAPONS[id]
    assert.equal(def.id, id)
    assert.ok(def.name.length > 0)
    assert.ok(def.damage > 0)
    assert.ok(def.rpm > 0)
    assert.ok(def.mag > 0)
    assert.ok(def.reserve >= 0)
    assert.ok(def.reload > 0)
    assert.ok(def.spread >= def.adsSpread)
    assert.equal(def.falloff.length, 2)
    assert.ok(def.falloff[0] < def.falloff[1])
    assert.ok(def.tracer >= 0 && def.tracer <= 0xffffff)
  }
})

test('loot weights reference real weapons and are positive', () => {
  const ids = new Set(LOOT_WEIGHTS.map((entry) => entry.id))
  assert.deepEqual([...ids].sort(), [...WEAPON_IDS].sort())
  for (const entry of LOOT_WEIGHTS) assert.ok(entry.weight > 0)
})

test('zone phases close monotonically into a final circle', () => {
  let previous = ZONE_START_RADIUS
  for (const phase of ZONE_PHASES) {
    assert.ok(phase.radius < previous, 'radius must shrink every phase')
    assert.ok(phase.wait > 0)
    assert.ok(phase.shrink > 0)
    assert.ok(phase.dps > 0)
    previous = phase.radius
  }
  assert.ok(ZONE_START_RADIUS > 0)
  assert.ok(ZONE_PHASES.at(-1).radius < 10)
})

test('build pieces each have a wood cost', () => {
  assert.ok(BUILD_PIECES.length >= 3)
  for (const piece of BUILD_PIECES) assert.ok(BUILD_COSTS[piece] > 0)
})

test('bot names are unique and cover the roster', () => {
  assert.equal(new Set(BOT_NAMES).size, BOT_NAMES.length)
  assert.ok(BOT_NAMES.length >= MATCH.botCount)
})

test('sites and lakes are unique and inside the map bounds', () => {
  const ids = new Set(SITES.map((site) => site.id))
  assert.equal(ids.size, SITES.length)
  assert.ok(SITES.length >= 7)
  for (const site of SITES) {
    assert.ok(Math.hypot(site.x, site.z) < 380)
    assert.ok(site.radius > 0 && site.flatten >= site.radius)
  }
  for (const lake of LAKES) {
    assert.ok(lake.radius > 0 && lake.depth > 0)
  }
})

test('every weapon has rarity presentation data', () => {
  for (const id of WEAPON_IDS) {
    assert.ok(RARITY[id], `missing rarity for ${id}`)
    assert.match(RARITY[id].color, /^#[0-9a-f]{6}$/i)
  }
})

import test from 'node:test'
import assert from 'node:assert/strict'
import {
  clamp,
  lerp,
  invLerp,
  smoothstep,
  damp,
  mod,
  mulberry32,
  shuffle,
  formatTime,
  angleDelta,
  rayAABB,
  raySphere,
  pointInCircle,
  resolveCircleBox,
  sampleGrid,
  weightedPick
} from '../src/utils.js'

test('scalar helpers', () => {
  assert.equal(clamp(5, 0, 1), 1)
  assert.equal(clamp(-2, 0, 1), 0)
  assert.equal(clamp(0.4, 0, 1), 0.4)
  assert.equal(lerp(10, 20, 0.25), 12.5)
  assert.equal(invLerp(10, 20, 15), 0.5)
  assert.equal(invLerp(5, 5, 9), 0)
  assert.equal(smoothstep(0, 1, -1), 0)
  assert.equal(smoothstep(0, 1, 2), 1)
  assert.equal(smoothstep(0, 1, 0.5), 0.5)
  assert.ok(damp(0, 10, 10, 1) > 9.9)
  assert.equal(mod(-1, 8), 7)
})

test('deterministic RNG and shuffle do not mutate input', () => {
  const a = mulberry32(1234)
  const b = mulberry32(1234)
  const seqA = Array.from({ length: 8 }, () => a())
  const seqB = Array.from({ length: 8 }, () => b())
  assert.deepEqual(seqA, seqB)
  assert.ok(seqA.every((v) => v >= 0 && v < 1))

  const input = [1, 2, 3, 4, 5]
  const shuffled = shuffle(mulberry32(7), input)
  assert.deepEqual(input, [1, 2, 3, 4, 5])
  assert.deepEqual([...shuffled].sort(), input)
})

test('formatTime clamps and pads', () => {
  assert.equal(formatTime(0), '0:00')
  assert.equal(formatTime(9.9), '0:09')
  assert.equal(formatTime(65), '1:05')
  assert.equal(formatTime(600), '10:00')
  assert.equal(formatTime(-3), '0:00')
})

test('angleDelta returns the shortest signed arc', () => {
  assert.ok(Math.abs(angleDelta(0, 0.1) - 0.1) < 1e-9)
  assert.ok(Math.abs(angleDelta(Math.PI - 0.1, -Math.PI + 0.1) - 0.2) < 1e-9)
  assert.ok(Math.abs(angleDelta(0, Math.PI * 2)) < 1e-9)
})

test('rayAABB hits, misses and respects maxDist', () => {
  const box = { minX: -1, maxX: 1, minY: -1, maxY: 1, minZ: -1, maxZ: 1 }
  assert.equal(rayAABB(0, 0, 5, 0, 0, -1, box), 4)
  assert.equal(rayAABB(0, 0, 5, 0, 0, 1, box), null)
  assert.equal(rayAABB(0, 0, 5, 0, 0, -1, box, 2), null)
  assert.equal(rayAABB(5, 5, 5, 0, 0, -1, box), null)
})

test('raySphere returns the near intersection', () => {
  const t = raySphere(0, 0, 5, 0, 0, -1, 0, 0, 0, 1)
  assert.ok(t !== null && Math.abs(t - 4) < 1e-9)
  assert.equal(raySphere(0, 0, 5, 0, 0, 1, 0, 0, 0, 1), null)
  assert.equal(raySphere(0, 0, 5, 0, 0, -1, 0, 0, 0, 1, 2), null)
})

test('circle and box resolve helpers', () => {
  assert.equal(pointInCircle(1, 1, 0, 0, 2), true)
  assert.equal(pointInCircle(2.1, 0, 0, 0, 2), false)

  const box = { minX: -1, maxX: 1, minZ: -1, maxZ: 1 }
  const push = resolveCircleBox(0.9, 0, 0.5, box)
  assert.ok(push)
  assert.ok(push.x > 1)
  assert.equal(resolveCircleBox(5, 5, 0.5, box), null)
})

test('sampleGrid interpolates a known grid and clamps at edges', () => {
  // 3x3 grid, 2 cells, size 2 => values at x,z in [-1, 1]
  const grid = new Float32Array([
    0, 1, 2,
    10, 11, 12,
    20, 21, 22
  ])
  assert.equal(sampleGrid(grid, 2, 2, -1, -1), 0)
  assert.equal(sampleGrid(grid, 2, 2, 0, -1), 1)
  assert.equal(sampleGrid(grid, 2, 2, 0, 0), 11)
  assert.equal(sampleGrid(grid, 2, 2, 1, 1), 22)
  assert.equal(sampleGrid(grid, 2, 2, 0.5, 0), 11.5)
  // Points far outside clamp to the edge cells.
  assert.equal(sampleGrid(grid, 2, 2, 99, 99), 22)
})

