})

import test from 'node:test'
import assert from 'node:assert/strict'
import { Zone } from '../src/zone.js'
import { ZONE_PHASES, ZONE_START_RADIUS } from '../src/config.js'

function makeZone() {
  const scene = { add() {} }
  return new Zone(scene, null)
}

test('zone starts centered with the configured radius', () => {
  const zone = makeZone()
  zone.reset()
  assert.equal(zone.radius, ZONE_START_RADIUS)
  assert.equal(zone.state, 'wait')
  assert.equal(zone.timer, ZONE_PHASES[0].wait)
  assert.equal(zone.outside(0, 0), false)
  assert.equal(zone.outside(0, ZONE_START_RADIUS + 1), true)
  assert.equal(zone.distanceInside(0, 0), ZONE_START_RADIUS)
  assert.equal(zone.damagePerSecond(), ZONE_PHASES[0].dps)
})

test('zone shrinks to the next phase radius and advances the phase', () => {
  const zone = makeZone()
  zone.reset()
  zone.start()
  zone.startShrink()
  assert.equal(zone.state, 'shrink')
  assert.equal(zone.targetRadius, ZONE_PHASES[0].radius)

  const step = 0.25
  for (let t = 0; t < ZONE_PHASES[0].shrink + 1; t += step) zone.update(step)

  assert.equal(zone.radius, ZONE_PHASES[0].radius)
  assert.equal(zone.state, 'wait')
  assert.equal(zone.phaseIndex, 1)
  assert.equal(zone.timer, ZONE_PHASES[1].wait)
  assert.equal(zone.damagePerSecond(), ZONE_PHASES[1].dps)
})

test('zone closure is monotonic across every phase', () => {
  const zone = makeZone()
  zone.reset()
  zone.start()
  const radii = [zone.radius]
  for (let phase = 0; phase < ZONE_PHASES.length; phase++) {
    // Burn the wait timer, then the shrink timer.
    zone.timer = 0
    zone.update(0.016)
    if (zone.state === 'shrink') {
      while (zone.state === 'shrink') {
        zone.update(1)
        radii.push(zone.radius)
      }
    }
  }
  for (let i = 1; i < radii.length; i++) {
    assert.ok(radii[i] <= radii[i - 1] + 1e-9, 'radius must never grow')
  }
  assert.ok(zone.final)
  assert.equal(zone.countdown, 'FINAL')
  assert.equal(zone.phaseLabel, 'FINAL ZONE')
})

test('zone center confinement follows the animated center', () => {
  const zone = makeZone()
  zone.reset()
  zone.center = { x: 40, z: -25 }
  zone.radius = 50
  assert.equal(zone.outside(40, -25), false)
  assert.equal(zone.outside(90.1, -25), true)
  assert.equal(zone.distanceInside(70, -25), 20)
})

import test from 'node:test'
import assert from 'node:assert/strict'
import * as THREE from 'three'
import { Building } from '../src/building.js'
import { BUILD_COSTS, BUILD_MAX_HP, MATCH } from '../src/config.js'

function makeBuilding({ wood = 100, height = 5, obstacles = [] } = {}) {
  const scene = { add() {}, remove() {} }
  const world = {
    textures: { wood: new THREE.Texture(), metal: new THREE.Texture() },
    obstacles,
    getHeight: () => height
  }
  const player = { pos: { x: 0, y: height, z: 0 }, yaw: 0, wood }
  return { building: new Building(scene, world, player, null, null, null), world, player }
}

test('piece bounds match the 4m grid', () => {
  const { building } = makeBuilding()
  const wall = building._boundsFor(0, 0, 5, 0, 'wall')
  assert.equal(wall.maxX - wall.minX, 4)
  assert.equal(wall.maxZ - wall.minZ, 0.32)
  assert.equal(wall.maxY - wall.minY, 3.15)

  const wallRotated = building._boundsFor(0, 0, 5, Math.PI / 2, 'wall')
  assert.equal(wallRotated.maxX - wallRotated.minX, 0.32)
  assert.equal(wallRotated.maxZ - wallRotated.minZ, 4)

  const floor = building._boundsFor(0, 0, 5, 0, 'floor')
  assert.equal(floor.maxX - floor.minX, 4)
  assert.equal(floor.maxZ - floor.minZ, 4)

  const ramp = building._boundsFor(0, 0, 5, 0, 'ramp')
  assert.equal(ramp.maxZ - ramp.minZ, 5)
  assert.equal(ramp.maxY - ramp.minY, 3.15)
})

test('validation accepts open ground and rejects water, poor players and overlap', () => {
  const { building, world, player } = makeBuilding()
  assert.equal(building._validate(4, 0, 5, 0, 'wall'), true)

  world.getHeight = () => 0
  assert.equal(building._validate(4, 0, 5, 0, 'wall'), false)

  world.getHeight = () => 5
  player.wood = BUILD_COSTS.wall - 1
  assert.equal(building._validate(4, 0, 5, 0, 'wall'), false)

  player.wood = 100
  world.obstacles = [{ minX: 3, maxX: 5, minY: 4, maxY: 8, minZ: -1, maxZ: 1, kind: 'plaster' }]
  assert.equal(building._validate(4, 0, 5, 0, 'wall'), false)
})

test('validation respects the structure cap and far placement', () => {
  const { building } = makeBuilding()
  building.structures = new Array(building.maxStructures).fill({ hp: 1, bounds: {} })
  assert.equal(building._validate(4, 0, 5, 0, 'wall'), false)

  building.structures = []
  assert.equal(building._validate(50, 0, 5, 0, 'wall'), false)
})

test('placing a wall spends wood and registers physics', () => {
  const { building, world, player } = makeBuilding({ wood: 100 })
  building.setActive(true)
  building.setPiece('wall')
  building.valid = true
  building.target.set(4, 0, 0)
  building.baseY = 5

  assert.equal(building.place(), true)
  assert.equal(player.wood, 100 - BUILD_COSTS.wall)
  assert.equal(building.structures.length, 1)
  assert.equal(building.structures[0].hp, BUILD_MAX_HP)
  assert.equal(world.dynamicObstacles ?? 0, 0)
})

test('inactive build mode cannot place', () => {
  const { building } = makeBuilding()
  building.valid = true
  assert.equal(building.place(), false)
})

test('building range uses the configured reach', () => {
  assert.ok(MATCH.buildRange > 0)
  const { building } = makeBuilding()
  assert.equal(building._validate(MATCH.buildRange, 0, 5, 0, 'wall'), true)
  assert.equal(building._validate(MATCH.buildRange + 3, 0, 5, 0, 'wall'), false)
})

